# ১ম অধ্যায়: বাস্তব সংখ্যা

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*বাস্তব সংখ্যার শ্রেণিবিন্যাস, মূলদ ও অমূলদ সংখ্যা, আবৃত্ত দশমিক ভগ্নাংশ, যোগ, বিয়োগ, গুণ, ভাগ ও আসন্ন মান।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> বাস্তব সংখ্যার শ্রেণিবিন্যাস করতে ও ব্যাখ্যা করতে পারব;
> মূলদ ও অমূলদ সংখ্যা চিহ্নিত করতে এবং প্রমাণ করতে পারব;
> আবৃত্ত দশমিক ভগ্নাংশকে সাধারণ ভগ্নাংশে রূপান্তর করতে পারব;
> আবৃত দশমিকের যোগ, বিয়োগ, গুণ ও ভাগ নির্ণয় করতে পারব;
> বাস্তব সংখ্যার আসন্ন মান এবং তাৎপর্যপূর্ণ অঙ্ক ব্যাখ্যা করতে পারব।

### 🔹 বিষয়: বাস্তব সংখ্যার শ্রেণিবিন্যাস ও মূলদ-অমূলদ সংখ্যার ধারণা
সকল মূলদ সংখ্যা এবং অমূলদ সংখ্যাকে বাস্তব সংখ্যা (Real Number) বলা হয়।
- স্বাভাবিক সংখ্যা (Natural Numbers, ℕ): 1, 2, 3, 4, ... ইত্যাদি গণনাযোগ্য সংখ্যাকে স্বাভাবিক সংখ্যা বা ধনাত্মক অখণ্ড সংখ্যা বলে।
- পূর্ণসংখ্যা (Integers, ℤ): শূন্যসহ সকল ধনাত্মক ও ঋণাত্মক অখণ্ড সংখ্যাকে পূর্ণসংখ্যা বলে। যেমন: ..., -3, -2, -1, 0, 1, 2, 3, ...
- মূলদ সংখ্যা (Rational Numbers, ℚ): যে সকল সংখ্যাকে p/q আকারে প্রকাশ করা যায়, যেখানে p ও q পূর্ণসংখ্যা এবং q ≠ 0, সেগুলোকে মূলদ সংখ্যা বলে। যেমন: 3/1 = 3, 5/2 = 2.5।
- অমূলদ সংখ্যা (Irrational Numbers): যে সকল সংখ্যাকে দুটি পূর্ণসংখ্যার ভগ্নাংশ p/q আকারে প্রকাশ করা যায় না, সেগুলোকে অমূলদ সংখ্যা বলে। পূর্ণবর্গ নয় এমন যেকোনো স্বাভাবিক সংখ্যার বর্গমূল একটি অমূলদ সংখ্যা। যেমন: √(2), √(3), √(5)।

### 🔹 বিষয়: আবৃত্ত দশমিক ভগ্নাংশ ও সাধারণ ভগ্নাংশে রূপান্তর
যে সকল দশমিক ভগ্নাংশে দশমিক বিন্দুর ডানদিকের অঙ্কগুলো একটি নির্দিষ্ট ক্রমে বারবার আসে, সেগুলোকে আবৃত্ত বা পৌনঃপুনিক দশমিক ভগ্নাংশ বলে।
আবৃত্ত দশমিককে সাধারণ ভগ্নাংশে রূপান্তরের সূত্র:
লব = (প্রদত্ত সংখ্যার সম্পূর্ণ অঙ্কগুলো নিয়ে গঠিত সংখ্যা - অনাবৃত্ত অংশের অঙ্কগুলো নিয়ে গঠিত সংখ্যা)
হর = (যতগুলো আবৃত্ত অঙ্ক ততগুলো ৯ বসবে, এর ডানে দশমিক বিন্দুর পর যতগুলো অনাবৃত্ত অঙ্ক ততগুলো ০ বসবে)

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১১ (বোর্ড উপপাদ্য): প্রমাণ কর যে, √(2) একটি অমূলদ সংখ্যা।**
> 💡 **সমাধান:**
> **ধাপ ১ (বিপরীত ধরে নেওয়া):**
> মনে করি, √(2) একটি অমূলদ সংখ্যা নয়; অর্থাৎ √(2) একটি মূলদ সংখ্যা।
> 
> **ধাপ ২ (মূলদ সংখ্যার সংজ্ঞানুযায়ী গঠন):**
> সুতরাং, এমন দুটি পরস্পর সহমৌলিক স্বাভাবিক সংখ্যা p ও q (q > 1) থাকবে যেন,
> √(2) = p/q
> 
> **ধাপ ৩ (উভয়পক্ষ বর্গকরণ):**
> উভয়পক্ষকে বর্গ করে পাই,
> 2 = p²/q²
> বা, উভয়পক্ষকে q দ্বারা গুণ করে পাই:
> 2q = p²/q
> 
> **ধাপ ৪ (যুক্তি ও বিশ্লেষণ):**
> স্পষ্টতই 2q একটি পূর্ণসংখ্যা (কারণ q একটি স্বাভাবিক সংখ্যা)।
> কিন্তু p²/q পূর্ণসংখ্যা নয়; কারণ p ও q পরস্পর সহমৌলিক স্বাভাবিক সংখ্যা এবং q > 1, ফলে p² ও q এর মধ্যে 1 ব্যতীত কোনো সাধারণ গুণনীয়ক নেই।
> সুতরাং, পূর্ণসংখ্যা 2q এবং ভগ্নাংশ p²/q কখনোই সমান হতে পারে না।
> অর্থাৎ, 2q ≠ p²/q।
> 
> **ধাপ ৫ (সিদ্ধান্ত):**
> অতএব, √(2) কে p/q আকারে প্রকাশ করা অসম্ভব।
> সুতরাং, √(2) মূলদ সংখ্যা হতে পারে না।
> 🎯 **প্রমাণিত:** √(2) একটি অমূলদ সংখ্যা।

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১২(ক): 1/6 ভগ্নাংশটিকে আবৃত্ত দশমিক ভগ্নাংশে প্রকাশ কর।**
> 💡 **সমাধান:**
> **ভাগ প্রক্রিয়া:**
> 1 কে 6 দিয়ে ভাগ করি:
>   1.0 ÷ 6
> = 0.1666...
> এখানে দশমিকের পর প্রথম অঙ্ক 1 অনাবৃত্ত এবং এরপর 6 অঙ্কটি বারবার আবৃত্ত হচ্ছে।
> অতএব, 1/6 = 0.16̇
> 🎯 **উত্তর:** 0.16̇

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১২(খ): 7/11 ভগ্নাংশটিকে আবৃত্ত দশমিক ভগ্নাংশে প্রকাশ কর।**
> 💡 **সমাধান:**
> **ভাগ প্রক্রিয়া:**
> 7 কে 11 দিয়ে ভাগ করি:
>   7.0 ÷ 11
> = 0.636363...
> এখানে দশমিকের পর 6 এবং 3 অঙ্কদ্বয় বারবার পর্যায়ক্রমে আসছে।
> অতএব, 7/11 = 0.6̇3̇
> 🎯 **উত্তর:** 0.6̇3̇

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১৩(ক, খ): আবৃত্ত দশমিককে সাধারণ ভগ্নাংশে প্রকাশ কর: (ক) 0.47̇ এবং (খ) 0.3̇**
> 💡 **সমাধান:**
> **(ক) 0.47̇ এর সমাধান:**
> অনাবৃত্ত অঙ্ক ১টি (4), আবৃত্ত অঙ্ক ১টি (7)।
> লব = 47 - 4 = 43
> হর = 90 (১টি ৯ ও ১টি ০)
> অতএব, নির্ণেয় ভগ্নাংশ = 43/90
> 🎯 উত্তর: 43/90
> 
> **(খ) 0.3̇ এর সমাধান:**
> অনাবৃত্ত অঙ্ক নেই, আবৃত্ত অঙ্ক ১টি (3)।
> লব = 3 - 0 = 3
> হর = 9
> অতএব, নির্ণেয় ভগ্নাংশ = 3/9 = 1/3
> 🎯 উত্তর: 1/3

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১৪: সদৃশ আবৃত্ত দশমিকে রূপান্তর কর: 2.3̇, 5.23̇5̇ এবং 0.457̇**
> 💡 **সমাধান:**
> **বিশ্লেষণ:**
> অনাবৃত্ত অংশের অঙ্ক সংখ্যা হবে সর্বোচ্চ অনাবৃত্ত অঙ্কের সমান = 2 (0.457̇ এর মধ্যে 4 ও 5)।
> আবৃত্ত অংশের অঙ্ক সংখ্যা হবে আবৃত্ত অঙ্কগুলোর লসাগু:
> 2.3̇ এ আবৃত্ত অঙ্ক ১টি
> 5.23̇5̇ এ আবৃত্ত অঙ্ক ২টি (3 ও 5)
> 0.457̇ এ আবৃত্ত অঙ্ক ১টি (7)
> ১, ২, ১ এর লসাগু = ২।
> সুতরাং প্রতিটি সংখ্যায় দশমিকের পর ২টি অনাবৃত্ত এবং ২টি আবৃত্ত অঙ্ক থাকবে:
> - 2.3̇ = 2.333̇3̇
> - 5.23̇5̇ = 5.235̇3̇
> - 0.457̇ = 0.457̇7̇
> 🎯 **উত্তর:** 2.333̇3̇, 5.235̇3̇, 0.457̇7̇

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১৫: যোগফল নির্ণয় কর: 0.45̇ + 0.134̇**
> 💡 **সমাধান:**
> **ধাপ ১ (সদৃশ আবৃত্ত দশমিকে রূপান্তর):**
> সর্বোচ্চ অনাবৃত্ত অঙ্ক = ১টি।
> আবৃত্ত অঙ্কগুলোর লসাগু (১ ও ১) = ১।
>   0.4555...
> + 0.1344...
> ------------
> = 0.5899...
> = 0.589̇
> 🎯 **উত্তর:** 0.589̇ (বা 0.59)

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১৭: গুণফল নির্ণয় কর: 0.62̇ × 0.3̇**
> 💡 **সমাধান:**
> **ধাপ ১ (সাধারণ ভগ্নাংশে রূপান্তর):**
> 0.62̇ = (62 - 6) / 90 = 56 / 90 = 28 / 45
> 0.3̇ = 3 / 9 = 1 / 3
> 
> **ধাপ ২ (গুণকরণ):**
> গুণফল = 28/45 × 1/3 = 28 / 135
> 
> **ধাপ ৩ (দশমিকে প্রকাশ):**
> 28 ÷ 135 = 0.2074074... = 0.20̇7̇4̇
> 🎯 **উত্তর:** 0.20̇7̇4̇ (বা 28/135)

> 🔢 **অনুশীলনী ১ • প্রশ্ন ১৯: প্রমাণ কর যে, দুটি ক্রমিক স্বাভাবিক সংখ্যার গুণফল সর্বদা জোড় সংখ্যা।**
> 💡 **সমাধান:**
> **প্রমাণ:**
> মনে করি, দুটি ক্রমিক স্বাভাবিক সংখ্যা যথাক্রমে x এবং x + 1; যেখানে x ∈ ℕ।
> এখন, এদের গুণফল = x(x + 1)।
> 
> ১ম ক্ষেত্র: যদি x জোড় সংখ্যা হয়, তবে x = 2k (যেখানে k ∈ ℕ)।
> তাহলে, গুণফল = 2k(2k + 1), যা 2 দ্বারা বিভাজ্য। অর্থাৎ গুণফলটি জোড় সংখ্যা।
> 
> ২য় ক্ষেত্র: যদি x বিজোড় সংখ্যা হয়, তবে x + 1 অবশ্যই জোড় সংখ্যা হবে।
> তাহলে, বিজোড় × জোড় = সর্বদা জোড় সংখ্যা।
> অতএব, উভয় ক্ষেত্রেই দুটি ক্রমিক স্বাভাবিক সংখ্যার গুণফল সর্বদা জোড় সংখ্যা।
> 🎯 **প্রমাণিত।**

