    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, $tag_math_ch02$
# ২য় অধ্যায়: সেট ও ফাংশন

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*সেটের ধারণা, তালিকা ও গঠন পদ্ধতি, উপসেট, শক্তি সেট, ভেনচিত্র, কার্তেসীয় গুণজ, অন্বয় এবং ফাংশনের ডোমেন ও রেঞ্জ।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> সেট ও উপসেটের ধারণা প্রতীকসহ ব্যাখ্যা করতে পারব;
> সেট প্রকাশের পদ্ধতি (তালিকা ও গঠন পদ্ধতি) প্রয়োগ করতে পারব;
> সংযোগ, ছেদ, অন্তর ও পূরক সেট নির্ণয় এবং ভেনচিত্রের মাধ্যমে প্রদর্শন করতে পারব;
> শক্তি সেট ও এর উপাদান সংখ্যার সূত্র 2ⁿ যাচাই করতে পারব;
> অন্বয় ও ফাংশন ব্যাখ্যা করতে পারব এবং ডোমেন ও রেঞ্জ নির্ণয় করতে পারব।

### 🔹 বিষয়: সেট প্রকাশের পদ্ধতি ও বিভিন্ন প্রকার সেট
১. তালিকা পদ্ধতি (Roster Method): এ পদ্ধতিতে সেটের সকল উপাদান সুনির্দিষ্টভাবে দ্বিতীয় বন্ধনী { } এর মধ্যে আবদ্ধ করা হয় এবং একাধিক উপাদান থাকলে কমা ব্যবহার করে পৃথক করা হয়। যেমন: A = {1, 2, 3}, B = {a, b, c}।
২. সেট গঠন পদ্ধতি (Set Builder Method): এ পদ্ধতিতে উপাদানের সুনির্দিষ্ট বৈশিষ্ট্য উল্লেখ থাকে। যেমন: A = {x : x স্বাভাবিক বিজোড় সংখ্যা এবং x < 10}।
- সসীম সেট (Finite Set): যে সেটের উপাদান সংখ্যা গণনা করে নির্ধারণ করা যায়।
- অসীম সেট (Infinite Set): যে সেটের উপাদান সংখ্যা গণনা করে শেষ করা যায় না। যেমন: স্বাভাবিক সংখ্যার সেট ℕ = {1, 2, 3, 4, ...}।
- ফাঁকা সেট (Empty Set): যে সেটের কোনো উপাদান নেই। একে ∅ দ্বারা প্রকাশ করা হয়।

### 🔹 বিষয়: সেট প্রক্রিয়া ও ভেনচিত্র
- সংযোগ সেট (Union of Sets, A ∪ B): দুই বা ততোধিক সেটের সকল উপাদান নিয়ে গঠিত সেট।
- ছেদ সেট (Intersection of Sets, A ∩ B): দুই বা ততোধিক সেটের সাধারণ (Common) উপাদান নিয়ে গঠিত সেট।
- অন্তর সেট (Difference of Sets, A ∖ B বা A - B): A সেটের যে সকল উপাদান B সেটের উপাদান নয়, তাদের নিয়ে গঠিত সেট।
- পূরক সেট (Complement Set, A' বা Aᶜ): সার্বিক সেট U থেকে A সেটের উপাদান বাদ দিয়ে গঠিত সেট (U ∖ A)।
- শক্তি সেট (Power Set, P(A)): কোনো সেটের সকল উপসেট নিয়ে গঠিত সেটকে ঐ সেটের শক্তি সেট বলে। কোনো সেটের উপাদান সংখ্যা n হলে, তার উপসেটের সংখ্যা 2ⁿ।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ২.১ • প্রশ্ন ১(ক): সেটটিকে তালিকা পদ্ধতিতে প্রকাশ কর: A = {x ∈ ℕ : x² > 9 এবং x³ < 130}**
> 💡 **সমাধান:**
> **ধাপ ১ (স্বাভাবিক সংখ্যা বিবেচনা):**
> আমরা জানি, স্বাভাবিক সংখ্যার সেট ℕ = {1, 2, 3, 4, 5, 6, ...}
> 
> **ধাপ ২ (শর্ত যাচাই):**
> - x = 1 হলে, x² = 1² = 1 (যা 9 অপেক্ষা বড় নয়); x³ = 1³ = 1 (< 130)
> - x = 2 হলে, x² = 2² = 4 (যা 9 অপেক্ষা বড় নয়); x³ = 2³ = 8 (< 130)
> - x = 3 হলে, x² = 3² = 9 (যা 9 অপেক্ষা বড় নয়); x³ = 3³ = 27 (< 130)
> - x = 4 হলে, x² = 4² = 16 > 9 এবং x³ = 4³ = 64 < 130 (উভয় শর্ত সত্য)
> - x = 5 হলে, x² = 5² = 25 > 9 এবং x³ = 5³ = 125 < 130 (উভয় শর্ত সত্য)
> - x = 6 হলে, x² = 6² = 36 > 9 কিন্তু x³ = 6³ = 216 (যা 130 অপেক্ষা ছোট নয়)
> 
> **ধাপ ৩ (উপাদান নির্ধারণ):**
> প্রদত্ত উভয় শর্ত পূরণ করে x = 4 এবং x = 5।
> অতএব, নির্ণেয় সেট A = {4, 5}।
> 🎯 **উত্তর:** {4, 5}

> 🔢 **অনুশীলনী ২.১ • প্রশ্ন ২(ক): সেটটিকে সেট গঠন পদ্ধতিতে প্রকাশ কর: {3, 5, 7, 9, 11}**
> 💡 **সমাধান:**
> **বিশ্লেষণ:**
> প্রদত্ত সেটের উপাদানসমূহ: 3, 5, 7, 9, 11।
> এখানে প্রতিটি উপাদান স্বাভাবিক সংখ্যা, প্রত্যেকে বিজোড় সংখ্যা এবং 1 অপেক্ষা বড় কিন্তু 13 অপেক্ষা ছোট (অথবা 3 থেকে 11 পর্যন্ত)।
> অতএব, সেট গঠন পদ্ধতি:
> {x ∈ ℕ : x বিজোড় সংখ্যা এবং 1 < x < 13} (বা 3 ≤ x ≤ 11)
> 🎯 **উত্তর:** {x ∈ ℕ : x বিজোড় সংখ্যা এবং 1 < x < 13}

> 🔢 **অনুশীলনী ২.১ • প্রশ্ন ৩: A = {2, 3, 4}, B = {1, 2, a} এবং C = {2, a, b} হলে নির্ণয় কর: (ক) A ∩ B এবং (খ) A ∪ (B ∩ C)**
> 💡 **সমাধান:**
> **(ক) A ∩ B নির্ণয়:**
> A ∩ B = {2, 3, 4} ∩ {1, 2, a}
> উভয় সেটের সাধারণ (কমন) উপাদান = {2}।
> অতএব, A ∩ B = {2}।
> 🎯 উত্তর: {2}
> 
> **(খ) A ∪ (B ∩ C) নির্ণয়:**
> প্রথমে, B ∩ C = {1, 2, a} ∩ {2, a, b} = {2, a}।
> এখন, A ∪ (B ∩ C) = {2, 3, 4} ∪ {2, a}
> সকল উপাদান নিয়ে গঠিত সেট = {2, 3, 4, a}।
> অতএব, A ∪ (B ∩ C) = {2, 3, 4, a}।
> 🎯 উত্তর: {2, 3, 4, a}

> 🔢 **অনুশীলনী ২.১ • প্রশ্ন ৬: A = {a, b}, B = {a, b, c} এবং C = A ∪ B হলে, দেখাও যে, P(C) এর উপাদান সংখ্যা 2ⁿ, যেখানে n হলো C এর উপাদান সংখ্যা।**
> 💡 **সমাধান:**
> **ধাপ ১ (C সেট নির্ণয়):**
> C = A ∪ B = {a, b} ∪ {a, b, c} = {a, b, c}
> এখানে C সেটের উপাদান সংখ্যা n = 3।
> 
> **ধাপ ২ (P(C) গঠন):**
> C এর উপসেটসমূহ:
> - ৩টি উপাদান নিয়ে: {a, b, c}
> - ২টি উপাদান নিয়ে: {a, b}, {a, c}, {b, c}
> - ১টি উপাদান নিয়ে: {a}, {b}, {c}
> - কোনো উপাদান না নিয়ে (ফাঁকা সেট): ∅
> অতএব, P(C) = {{a, b, c}, {a, b}, {a, c}, {b, c}, {a}, {b}, {c}, ∅}
> 
> **ধাপ ৩ (উপাদান সংখ্যা যাচাই):**
> P(C) এর উপাদান সংখ্যা = 8 = 2³ = 2ⁿ (যেহেতু n = 3)।
> সুতরাং, P(C) এর উপাদান সংখ্যা 2ⁿ কে সমর্থন করে।
> 🎯 **প্রমাণিত।**

> 🔢 **অনুশীলনী ২.২ • প্রশ্ন ১০: যদি A = {3, 4}, B = {2, 4} হয়, তবে A ও B এর উপাদানগুলোর মধ্যে x > y সম্পর্ক বিবেচনা করে অন্বয়টি (R) নির্ণয় কর।**
> 💡 **সমাধান:**
> **ধাপ ১ (কার্তেসীয় গুণজ নির্ণয়):**
> A × B = {3, 4} × {2, 4}
> = {(3, 2), (3, 4), (4, 2), (4, 4)}
> 
> **ধাপ ২ (শর্ত x > y প্রয়োগ):**
> - (3, 2) এর ক্ষেত্রে 3 > 2 (সত্য)
> - (3, 4) এর ক্ষেত্রে 3 > 4 (মিথ্যা)
> - (4, 2) এর ক্ষেত্রে 4 > 2 (সত্য)
> - (4, 4) এর ক্ষেত্রে 4 > 4 (মিথ্যা)
> 
> অতএব, অন্বয় R = {(3, 2), (4, 2)}।
> 🎯 **উত্তর:** R = {(3, 2), (4, 2)}

> 🔢 **অনুশীলনী ২.২ • প্রশ্ন ১২: f(x) = x⁴ + 5x - 3 হলে, f(-1), f(2) এবং f1/2 এর মান নির্ণয় কর।**
> 💡 **সমাধান:**
> **১ম অংশ: f(-1)**
> f(-1) = (-1)⁴ + 5(-1) - 3 = 1 - 5 - 3 = -7
> 🎯 f(-1) = -7
> 
> **২য় অংশ: f(2)**
> f(2) = (2)⁴ + 5(2) - 3 = 16 + 10 - 3 = 23
> 🎯 f(2) = 23
> 
> **৩য় অংশ: f1/2**
> f1/2 = 1/2⁴ + 51/2 - 3 = 1/16 + 5/2 - 3
> = (1 + 40 - 48) / 16 = -7/16
> 🎯 f1/2 = -7/16

$tag_math_ch02$, 1);

