> 🎯 **উত্তর:** পূর্ণক: $0$, অংশক: $0.14768$

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ৯(ঘ): ক্যালকুলেটর ব্যবহার করে $0.0456$-এর সাধারণ লগের পূর্ণক ও অংশক নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত সংখ্যা:** $0.0456$
> 
> **ধাপ ১ (ক্যালকুলেটর হতে মান প্রাপ্তি):**
> ক্যালকুলেটরে ইনপুট: $\log 0.0456 =$
> প্রদর্শিত মান: $\approx -1.341035\dots$
> 
> **ধাপ ২ (সতর্কতা: অংশক সর্বদা অঋণাত্মক হতে হবে):**
> আমরা জানি, $-1.34104 = -1 - 0.34104$। কিন্তু অংশক কখনো ঋণাত্মক হতে পারে না।
> তাই এতে $-1$ ও $+1$ যোগ করে পাই:
> $= -1 - 1 + (1 - 0.34104)$
> $= -2 + 0.65896$
> $= \bar{2}.65896$
> 
> **ধাপ ৩ (পূর্ণক ও অংশক নির্ধারণ):**
> পূর্ণক $= -2$ বা $\bar{2}$
> অংশক $= .65896$
> 🎯 **উত্তর:** পূর্ণক: $\bar{2}$ (বা $-2$), অংশক: $0.65896$

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ৯(ঙ): ক্যালকুলেটর ব্যবহার করে $0.000673$-এর সাধারণ লগের পূর্ণক ও অংশক নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত সংখ্যা:** $0.000673$
> 
> **ধাপ ১ (ক্যালকুলেটরের মান):**
> ক্যালকুলেটরে ইনপুট: $\log 0.000673 =$
> প্রদর্শিত মান: $\approx -3.1719849\dots$
> 
> **ধাপ ২ (অংশককে ধনাত্মক রূপে রূপান্তর):**
