> $= -3 - 1 + (1 - 0.17198)$
> $= -4 + 0.82802$
> $= \bar{4}.82802$
> 
> **ধাপ ৩ (পূর্ণক ও অংশক নির্ধারণ):**
> পূর্ণক $= -4$ বা $\bar{4}$
> অংশক $= .82802$
> 🎯 **উত্তর:** পূর্ণক: $\bar{4}$ (বা $-4$), অংশক: $0.82802$

#### 🔹 গুণফল ও ভাগফলের সাধারণ লগ নির্ণয় করো (প্রশ্ন ১০)

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ১০(ক): গুণফলের সাধারণ লগ (আসন্ন পাঁচ দশমিক স্থান পর্যন্ত) নির্ণয় করো: $5.34 \times 8.7$**
> 💡 **সমাধান:**
> **প্রদত্ত রাশি:** $5.34 \times 8.7$
> 
> **ধাপ ১ (লগারিদমের গুণের সূত্র প্রয়োগ):**
> $\log(5.34 \times 8.7) = \log 5.34 + \log 8.7$
> 
> **ধাপ ২ (ক্যালকুলেটর ব্যবহার করে আলাদা মান নির্ণয়):**
> $\log 5.34 \approx 0.727541$
> $\log 8.7 \approx 0.939519$
> 
> **ধাপ ৩ (যোগফল নির্ণয়):**
> $= 0.727541 + 0.939519$
> $= 1.66706$ (আসন্ন পাঁচ দশমিক স্থান পর্যন্ত)
> 🎯 **উত্তর:** $1.66706$

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ১০(খ): গুণফলের সাধারণ লগ (আসন্ন পাঁচ দশমিক স্থান পর্যন্ত) নির্ণয় করো: $0.79 \times 0.56$**
> 💡 **সমাধান:**
> **প্রদত্ত রাশি:** $0.79 \times 0.56$
> 
> **ধাপ ১ (লগারিদমের গুণের সূত্র প্রয়োগ):**
> $\log(0.79 \times 0.56) = \log 0.79 + \log 0.56$
> 
> **ধাপ ২ (ক্যালকুলেটর ব্যবহার করে মান গ্রহণ):**
> $\log 0.79 \approx -0.102373$
> $\log 0.56 \approx -0.251812$
> 
> **ধাপ ৩ (বীজগাণিতিক যোগফল ও মান রূপান্তর):**
> $= -0.102373 + (-0.251812)$
> $= -0.354185$
> আসন্ন পাঁচ দশমিক স্থানে: $-0.35419$
> [ধনাত্মক অংশক আকারে প্রকাশ করলে: $-1 + (1 - 0.35419) = \bar{1}.64581$]
> 🎯 **উত্তর:** $-0.35419$ (বা $\bar{1}.64581$)

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ১০(গ): ভাগফলের সাধারণ লগ (আসন্ন পাঁচ দশমিক স্থান পর্যন্ত) নির্ণয় করো: $22.2642 \div 3.42$**
> 💡 **সমাধান:**
> **প্রদত্ত রাশি:** $22.2642 \div 3.42$
> 
> **ধাপ ১ (লগারিদমের ভাগের সূত্র প্রয়োগ):**
> $\log(22.2642 \div 3.42) = \log 22.2642 - \log 3.42$
> 
> **ধাপ ২ (ক্যালকুলেটর থেকে মান সংগ্রহ):**
> $\log 22.2642 \approx 1.347605$
> $\log 3.42 \approx 0.534026$
> 
> **ধাপ ৩ (বিয়োগফল নির্ণয়):**
> $= 1.347605 - 0.534026$
> $= 0.813579 \approx 0.81358$ (আসন্ন পাঁচ দশমিক স্থান পর্যন্ত)
> 🎯 **উত্তর:** $0.81358$

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ১০(ঘ): ভাগফলের সাধারণ লগ (আসন্ন পাঁচ দশমিক স্থান পর্যন্ত) নির্ণয় করো: $0.19926 \div 32.4$**
> 💡 **সমাধান:**
> **প্রদত্ত রাশি:** $0.19926 \div 32.4$
> 
> **ধাপ ১ (লগারিদমের ভাগের সূত্র প্রয়োগ):**
> $\log(0.19926 \div 32.4) = \log 0.19926 - \log 32.4$
> 
> **ধাপ ২ (মান বসিয়ে):**
> $\log 0.19926 \approx -0.700577$
> $\log 32.4 \approx 1.510545$
> 
> **ধাপ ৩ (বিয়োগফল নির্ণয়):**
> $= -0.700577 - 1.510545$
> $= -2.211122 \approx -2.21112$
> [বার আকারে প্রকাশ করলে: $-2 - 1 + (1 - 0.21112) = -3 + 0.78888 = \bar{3}.78888$]
> 🎯 **উত্তর:** $-2.21112$ (বা $\bar{3}.78888$)

#### 🔹 মান নির্ণয় করো (প্রশ্ন ১১)

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ১১(ক): যদি $\log 2 = 0.30103, \log 3 = 0.47712$ এবং $\log 7 = 0.85410$ হয়, তবে $\log 9$-এর মান নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত মানসমূহ:**
> $\log 2 = 0.30103$
> $\log 3 = 0.47712$
> $\log 7 = 0.85410$
> 
> **ধাপ ১ (৯-কে ৩-এর ঘাত আকারে প্রকাশ):**
> $\log 9 = \log (3^2)$
> 
> **ধাপ ২ (ঘাতের সূত্র প্রয়োগ):**
> $= 2 \cdot \log 3$
> 
> **ধাপ ৩ (মান বসিয়ে গুণন):**
> $= 2 \times 0.47712$
> $= 0.95424$
> 🎯 **উত্তর:** $0.95424$

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ১১(খ): যদি $\log 2 = 0.30103, \log 3 = 0.47712$ এবং $\log 7 = 0.85410$ হয়, তবে $\log 28$-এর মান নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত রাশি:** $\log 28$
> 
> **ধাপ ১ (২৮-কে মৌলিক উৎপাদকে বিশ্লেষণ):**
> $28 = 4 \times 7 = 2^2 \times 7$
> 
> **ধাপ ২ (লগের গুণের ও ঘাতের সূত্র প্রয়োগ):**
> $\log 28 = \log (2^2 \times 7)$
> $= \log (2^2) + \log 7$
> $= 2\log 2 + \log 7$
> 
> **ধাপ ৩ (মান বসিয়ে যোগফল নির্ণয়):**
> $= 2(0.30103) + 0.85410$
> $= 0.60206 + 0.85410$
> $= 1.45616$
> 🎯 **উত্তর:** $1.45616$

> 🔢 **অনুশীলনী ৪.৩ • প্রশ্ন ১১(গ): যদি $\log 2 = 0.30103, \log 3 = 0.47712$ এবং $\log 7 = 0.85410$ হয়, তবে $\log 42$-এর মান নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত রাশি:** $\log 42$
> 
> **ধাপ ১ (৪২-কে মৌলিক উৎপাদকে বিশ্লেষণ):**
> $42 = 2 \times 21 = 2 \times 3 \times 7$
> 
> **ধাপ ২ (লগের গুণের সূত্র প্রয়োগ):**
> $\log 42 = \log (2 \times 3 \times 7)$
> $= \log 2 + \log 3 + \log 7$
> 
> **ধাপ ৩ (মানগুলো বসিয়ে যোগফল গ্রহণ):**
> $= 0.30103 + 0.47712 + 0.85410$
> $= 1.63225$
> 🎯 **উত্তর:** $1.63225$

### 📘 অধ্যায় ৪ এর নমুনা প্রশ্ন ও বোর্ড স্ট্যান্ডার্ড সৃজনশীল/সংক্ষিপ্ত প্রশ্নাবলি

#### 🔹 নমুনা বহুনির্বাচনি প্রশ্নাবলি (পৃষ্ঠা ৯২)

> 🔢 **নমুনা প্রশ্ন • বহুনির্বাচনি ১: $\log_x 4 = 2$ হলে, $x$ এর মান কত?**
> ক) $2$
> খ) $\pm 2$
> গ) $4$
> ঘ) $10$
> 💡 **সমাধান:**
> **ব্যাখ্যা:**
> লগারিদমের সংজ্ঞানুসারে:
> $\log_x 4 = 2 \iff x^2 = 4$
> $\Rightarrow x = \pm 2$
> কিন্তু আমরা জানি, লগারিদমের ভিত্তি সর্বদা ধনাত্মক এবং এক ব্যতীত অন্য সংখ্যা ($x > 0, x \ne 1$)।
> সুতরাং $x = -2$ গ্রহণযোগ্য নয়।
> অতএব, $x = 2$।
> 🎯 **সঠিক উত্তর:** ক) $2$

> 🔢 **নমুনা প্রশ্ন • বহুনির্বাচনি ২: $a = \log_2 3, b = \log_2 5$ হলে—**
> (i) $\frac{a}{b} = \log_5 3$
> (ii) $a + b = \log_2 15$
> (iii) $a^2 + b^2 = 8$
> নিচের কোনটি সঠিক?
> ক) $i$ ও $ii$
> খ) $i$ ও $iii$
> গ) $ii$ ও $iii$
> ঘ) $i, ii$ ও $iii$
> 💡 **সমাধান:**
> **যাচাইকরণ:**
> (i) $\frac{a}{b} = \frac{\log_2 3}{\log_2 5} = \log_5 3$ (ভিত্তি পরিবর্তন সূত্র মতে সত্য)।
> (ii) $a + b = \log_2 3 + \log_2 5 = \log_2 (3 \times 5) = \log_2 15$। (পাঠ্যবইয়ের মুদ্রণ সংশোধন সাপেক্ষে সত্য)।
> (iii) $a^2 + b^2 = (\log_2 3)^2 + (\log_2 5)^2 \ne 8$ (মিথ্যা)।
> অতএব (i) ও (ii) সঠিক।
> 🎯 **সঠিক উত্তর:** ক) $i$ ও $ii$

> 🔢 **নমুনা প্রশ্ন • বহুনির্বাচনি ৩: $0.0225$ সংখ্যাটি বিবেচনা করো। সংখ্যাটির বৈজ্ঞানিক আকার নিচের কোনটি?**
> ক) $225 \times 10^{-4}$
> খ) $22.5 \times 10^{-3}$
> গ) $2.25 \times 10^{-2}$
> ঘ) $.225 \times 10^{-1}$
> 💡 **সমাধান:**
> **ব্যাখ্যা:**
> বৈজ্ঞানিক রূপ হলো $a \times 10^n$, যেখানে $1 \le a < 10$।
> $0.0225$-এ প্রথম সার্থক অঙ্ক $2$-এর পর দশমিক স্থাপন করলে $a = 2.25$ হয়।
> দশমিক বিন্দু ডানে ২ ঘর সরিয়ে নেওয়ায়:
> $0.0225 = 2.25 \times 10^{-2}$।
> 🎯 **সঠিক উত্তর:** গ) $2.25 \times 10^{-2}$

> 🔢 **নমুনা প্রশ্ন • বহুনির্বাচনি ৪: $0.0225$ সংখ্যাটির সাধারণ লগের পূর্ণক কত?**
> ক) $\bar{2}$
> খ) $\bar{1}$
> গ) $0$
> ঘ) $2$
> 💡 **সমাধান:**
> **ব্যাখ্যা:**
> যেহেতু বৈজ্ঞানিক আকার $2.25 \times 10^{-2}$, এতে $10$-এর ঘাত $-2$।
> অতএব সংখ্যাটির সাধারণ লগের পূর্ণক $-2$ বা $\bar{2}$।
> (বিকল্প পদ্ধতি: দশমিকের পর প্রথম অশূন্য অঙ্ক $2$-এর পূর্বে ১টি শূন্য বিদ্যমান। সুতরাং পূর্ণক $= -(1 + 1) = -2 = \bar{2}$)।
> 🎯 **সঠিক উত্তর:** ক) $\bar{2}$

#### 🔹 নমুনা সৃজনশীল প্রশ্ন (প্রশ্ন ৫)

> 🔢 **নমুনা প্রশ্ন • সৃজনশীল ৫(ক): উদ্দীপক: $A = \frac{7\log(\frac{16}{15}) + 5\log(\frac{25}{24}) - 13\log(\frac{2}{3})}{\log 3 + 3\log 5}$, $B = \frac{3^{2x+3} - 9 \cdot 3^{2x-1}}{3^{x+2} \div 3}$। $\sqrt{3}$ ভিত্তিতে $9$ এর লগ নির্ণয় করো।**
> 💡 **সমাধান:**
> **ধাপ ১ (লগারিদমিক আকার গঠন):**
> নির্ণেয় লগ $= \log_{\sqrt{3}} 9$
> 
> **ধাপ ২ (৯-কে ভিত্তি $\sqrt{3}$-এর ঘাত আকারে প্রকাশ):**
> $9 = 3^2 = ((\sqrt{3})^2)^2 = (\sqrt{3})^4$
> 
> **ধাপ ৩ (লগের ঘাতের সূত্র প্রয়োগ):**
> $= \log_{\sqrt{3}} (\sqrt{3})^4$
> $= 4 \cdot \log_{\sqrt{3}} \sqrt{3}$
> $= 4 \times 1 = 4$
> 🎯 **উত্তর:** $4$

> 🔢 **নমুনা প্রশ্ন • সৃজনশীল ৫(খ): উদ্দীপক: $A = \frac{7\log(\frac{16}{15}) + 5\log(\frac{25}{24}) - 13\log(\frac{2}{3})}{\log 3 + 3\log 5}$। দেখাও যে, $A = 1$**
> 💡 **সমাধান:**
> **ধাপ ১ ($A$-এর লবের প্রতিটি পদের বিশ্লেষণ):**
> লব $= 7\log\left(\frac{16}{15}\right) + 5\log\left(\frac{25}{24}\right) - 13\log\left(\frac{2}{3}\right)$
> 
> মৌলিক উৎপাদকে প্রকাশ করে:
> $\frac{16}{15} = \frac{2^4}{3 \times 5} \Rightarrow 7\log\left(\frac{16}{15}\right) = 7[4\log 2 - \log 3 - \log 5] = 28\log 2 - 7\log 3 - 7\log 5$
> 
> $\frac{25}{24} = \frac{5^2}{2^3 \times 3} \Rightarrow 5\log\left(\frac{25}{24}\right) = 5[2\log 5 - 3\log 2 - \log 3] = 10\log 5 - 15\log 2 - 5\log 3$
> 
> $\frac{2}{3} \Rightarrow -13\log\left(\frac{2}{3}\right) = -13[\log 2 - \log 3] = -13\log 2 + 13\log 3$
> 
> **ধাপ ২ (লবের পদসমূহের সদৃশ পদ যোগ-বিয়োগ):**
> $\log 2$-এর সহগ $= 28 - 15 - 13 = 28 - 28 = 0$
> $\log 3$-এর সহগ $= -7 - 5 + 13 = -12 + 13 = 1$
> $\log 5$-এর সহগ $= -7 + 10 = 3$
> 
> অতএব, লব $= 0\cdot\log 2 + 1\cdot\log 3 + 3\cdot\log 5 = \log 3 + 3\log 5$
> 
> **ধাপ ৩ (ভগ্নাংশ $A$-এর মান নির্ণয়):**
> $A = \frac{\text{লব}}{\text{হর}} = \frac{\log 3 + 3\log 5}{\log 3 + 3\log 5} = 1$
> 🎯 **সিদ্ধান্ত:** $A = 1$ (দেখানো হলো)

> 🔢 **নমুনা প্রশ্ন • সৃজনশীল ৫(গ): উদ্দীপক: $B = \frac{3^{2x+3} - 9 \cdot 3^{2x-1}}{3^{x+2} \div 3}$। $B = 72$ হলে, $x$ এর মান নির্ণয় করো।**
> 💡 **সমাধান:**
> **ধাপ ১ ($B$-এর লব সরলীকরণ):**
> লব $= 3^{2x+3} - 9 \cdot 3^{2x-1}$
> $= 3^{2x} \cdot 3^3 - 3^2 \cdot 3^{2x-1}$
> $= 27 \cdot 3^{2x} - 3^{2 + 2x - 1}$
> $= 27 \cdot 3^{2x} - 3^{2x + 1}$
> $= 27 \cdot 3^{2x} - 3 \cdot 3^{2x}$
> $= (27 - 3) \cdot 3^{2x} = 24 \cdot 3^{2x}$
> 
> **ধাপ ২ ($B$-এর হর সরলীকরণ):**
> হর $= 3^{x+2} \div 3^1 = 3^{x+2-1} = 3^{x+1} = 3 \cdot 3^x$
> 
> **ধাপ ৩ ($B$-এর মান নির্ণয়):**
> $B = \frac{24 \cdot 3^{2x}}{3 \cdot 3^x} = 8 \cdot 3^{2x - x} = 8 \cdot 3^x$
> 
> **ধাপ ৪ (সমীকরণ সমাধান):**
> দেওয়া আছে, $B = 72$
> $\Rightarrow 8 \cdot 3^x = 72$
> $\Rightarrow 3^x = \frac{72}{8} = 9$
> $\Rightarrow 3^x = 3^2$
> 
> উভয় পক্ষের ভিত্তি ৩ সমান হওয়ায়:
> $x = 2$
> 🎯 **উত্তর:** নির্ণেয় মান: $x = 2$

#### 🔹 সংক্ষিপ্ত-উত্তর প্রশ্নাবলি (প্রশ্ন ৬)

> 🔢 **নমুনা প্রশ্ন • সংক্ষিপ্ত প্রশ্ন ৬(ক): দেখাও যে, $\frac{25^n - 4}{5^n + 2} + 2 = 5^n$**
> 💡 **সমাধান:**
> **বামপক্ষ:**
> $= \frac{25^n - 4}{5^n + 2} + 2$
> 
> **ধাপ ১ ($25^n$-কে ঘাত আকারে বিশ্লেষণ):**
> $25^n = (5^2)^n = (5^n)^2$
> $4 = 2^2$
> লব $= (5^n)^2 - 2^2 = (5^n + 2)(5^n - 2)$
> 
> **ধাপ ২ (ভগ্নাংশ লঘুকরণ):**
> $= \frac{(5^n + 2)(5^n - 2)}{5^n + 2} + 2$
> $= (5^n - 2) + 2$
> $= 5^n$
> $= \text{ডানপক্ষ}$
> 🎯 **সিদ্ধান্ত:** $\frac{25^n - 4}{5^n + 2} + 2 = 5^n$ (দেখানো হলো)

> 🔢 **নমুনা প্রশ্ন • সংক্ষিপ্ত প্রশ্ন ৬(খ): $(\sqrt[3]{a})^{x-2} = 1$ হলে, $x$-এর মান নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত সমীকরণ:**
> $(\sqrt[3]{a})^{x-2} = 1$ ($a > 0, a \ne 1$)
> 
> **ধাপ ১ (সূচকীয় রূপান্তর):**
> $\sqrt[3]{a} = a^{\frac{1}{3}}$
> বা, $(a^{\frac{1}{3}})^{x-2} = 1$
> বা, $a^{\frac{x-2}{3}} = a^0$ [যেহেতু $a^0 = 1$]
> 
> **ধাপ ২ (সূচক সমতাকরণ):**
> $\frac{x-2}{3} = 0$
> $\Rightarrow x - 2 = 0 \times 3 = 0$
> $\Rightarrow x = 2$
> 🎯 **উত্তর:** নির্ণেয় মান: $x = 2$

> 🔢 **নমুনা প্রশ্ন • সংক্ষিপ্ত প্রশ্ন ৬(গ): $\log_y 27 = 6$ হলে, $y$-এর মান নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত সমীকরণ:**
> $\log_y 27 = 6$
> 
> **ধাপ ১ (সূচকীয় সমীকরণে প্রকাশ):**
> লগের সংজ্ঞানুসারে:
> $y^6 = 27$
> 
> **ধাপ ২ (২৭-কে ঘাত আকারে বিশ্লেষণ):**
> $27 = 3^3 = ((\sqrt{3})^2)^3 = (\sqrt{3})^6$
> 
> **ধাপ ৩ (উভয় পক্ষের ঘাত ৬ সমান হওয়ায় ভিত্তি সমতা):**
> $y^6 = (\sqrt{3})^6$
> যেহেতু উভয় পক্ষে ঘাত সমান এবং $y > 0$,
> $\Rightarrow y = \sqrt{3}$
> 🎯 **উত্তর:** নির্ণেয় মান: $y = \sqrt{3}$

> 🔢 **নমুনা প্রশ্ন • সংক্ষিপ্ত প্রশ্ন ৬(ঘ): ক্যালকুলেটর ব্যবহার না করে $1234567$-এর সাধারণ লগের পূর্ণক নির্ণয় করো।**
> 💡 **সমাধান:**
> **প্রদত্ত সংখ্যা:** $1234567$
> 
> **ধাপ ১ (অংক সংখ্যা গণনা):**
> সংখ্যাটি $1$-এর চেয়ে বড় একটি পূর্ণসংখ্যা।
> এতে দশমিকের পূর্বে মোট অঙ্ক সংখ্যা $k = 7$ (যেহেতু সংখ্যাটিতে ৭টি ডিজিট রয়েছে: ১, ২, ৩, ৪, ৫, ৬, ৭)।
> 
> **ধাপ ২ (পূর্ণকের সূত্র প্রয়োগ):**
> আমরা জানি, $1$-এর চেয়ে বড় সংখ্যার লগের পূর্ণক = (দশমিকের আগের মোট অঙ্ক সংখ্যা $- 1$)
> অতএব, পূর্ণক $= 7 - 1 = 6$।
> 
> **বিকল্প যাচাইকরণ (বৈজ্ঞানিক রূপ):**
> $1234567 = 1.234567 \times 10^6$
> এখানে $10$-এর সূচক হলো $6$, অতএব লগের পূর্ণক $= 6$।
> 🎯 **উত্তর:** সাধারণ লগের পূর্ণক $6$
