# ৫ম অধ্যায়: এক চলকবিশিষ্ট সমীকরণ

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*চলক ও ধ্রুবক, সমীকরণ ও অভেদের পার্থক্য, একঘাত সমীকরণ সমাধান, দ্বিঘাত সমীকরণ সমাধান এবং বাস্তব সমস্যার গাণিতিক রূপ।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> সমীকরণ ও অভেদের পার্থক্য ব্যাখ্যা করতে পারব;
> এক চলকবিশিষ্ট একঘাত সমীকরণ সমাধান ও সমাধান সেট নির্ণয় করতে পারব;
> দ্বিঘাত সমীকরণ সমাধান করতে পারব;
> বাস্তবভিত্তিক সমস্যার সমীকরণ গঠন ও সমাধান করতে পারব।

### 🔹 বিষয়: সমীকরণ ও অভেদ (Equation and Identity)
১. সমীকরণ: সমান চিহ্নের উভয়পক্ষে দুটি বীজগাণিতিক রাশি থাকে এবং চলকের এক বা একাধিক নির্দিষ্ট মানের জন্য সমতাটি সত্য হয়।
২. অভেদ: সমান চিহ্নের উভয়পক্ষের রাশি চলকের সকল মানের জন্য সমান হয়। যেমন: (a + b)² = a² + 2ab + b² একটি অভেদ।
- সকল অভেদই সমীকরণ, কিন্তু সকল সমীকরণ অভেদ নয়।
- অভেদে সমান চিহ্নের পরিবর্তে সচরাচর তিনটি রেখা (≡) ব্যবহার করা হয়।

### 🔹 বিষয়: দ্বিঘাত সমীকরণ সমাধানের নিয়মাবলী
এক চলকবিশিষ্ট আদর্শ দ্বিঘাত সমীকরণ: ax² + bx + c = 0 (যেখানে a ≠ 0)।
সমাধানের নিয়ম:
১. উৎপাদক পদ্ধতির মাধ্যমে: বামপক্ষকে উৎপাদকে বিশ্লেষণ করে প্রতিটি উৎপাদক সমান শূন্য ধরে সমাধান নির্ণয়।
২. দ্বিঘাত সূত্রের মাধ্যমে: x = (-b ± √(b² - 4ac)) / 2a
- নিশ্চায়ক (Discriminant): D = b² - 4ac
  - D > 0 এবং পূর্ণবর্গ হলে মূলদ্বয় বাস্তব, অসমান ও মূলদ।
  - D = 0 হলে মূলদ্বয় বাস্তব ও পরস্পর সমান (x = -b / 2a)।
  - D < 0 হলে কোনো বাস্তব মূল নেই।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ৫.১ • প্রশ্ন ১: সমাধান কর: (y + 1) / 2 - (y - 2) / 3 = (y - 3) / 4**
> 💡 **সমাধান:**
> **সমাধান:**
> প্রদত্ত সমীকরণ: (y + 1) / 2 - (y - 2) / 3 = (y - 3) / 4
> হরগুলোর (2, 3, 4) লসাগু = 12।
> উভয়পক্ষকে 12 দ্বারা গুণ করে পাই:
> 12 · ((y + 1) / 2) - 12 · ((y - 2) / 3) = 12 · ((y - 3) / 4)
> বা, 6(y + 1) - 4(y - 2) = 3(y - 3)
> বা, 6y + 6 - 4y + 8 = 3y - 9
> বা, 2y + 14 = 3y - 9
> পক্ষান্তর করে পাই:
> বা, 2y - 3y = -9 - 14
> বা, -y = -23
> বা, y = 23
> 🎯 **উত্তর:** y = 23

> 🔢 **অনুশীলনী ৫.১ • প্রশ্ন ৩: সমাধান কর: (x + a) / (x - b) = (x - a) / (x + b)**
> 💡 **সমাধান:**
> **সমাধান:**
> বজ্রগুণন (আড়গুণন) করে পাই:
> (x + a)(x + b) = (x - a)(x - b)
> বা, x² + (a + b)x + ab = x² - (a + b)x + ab
> উভয়পক্ষ থেকে x² এবং ab বাদ দিয়ে পাই:
> (a + b)x = -(a + b)x
> বা, (a + b)x + (a + b)x = 0
> বা, 2(a + b)x = 0
> যেহেতু a + b ≠ 0, তাই:
> x = 0
> 🎯 **উত্তর:** x = 0

> 🔢 **অনুশীলনী ৫.২ • প্রশ্ন ১১: সমাধান কর: (x + 2) / (x - 2) - 10 · ((x - 2) / (x + 2)) = 3**
> 💡 **সমাধান:**
> **সমাধান:**
> ধরি, (x + 2) / (x - 2) = a
> তাহলে, (x - 2) / (x + 2) = 1/a
> প্রদত্ত সমীকরণে মান বসাই:
> a - 101/a = 3
> বা, a - 10/a = 3
> উভয়পক্ষকে a দ্বারা গুণ করে পাই:
> a² - 10 = 3a
> বা, a² - 3a - 10 = 0
> মধ্যপদ বিভাজন করি:
> a² - 5a + 2a - 10 = 0
> বা, a(a - 5) + 2(a - 5) = 0
> বা, (a - 5)(a + 2) = 0
> 
> অতএব, হয় a - 5 = 0 ⇒ a = 5
> অথবা a + 2 = 0 ⇒ a = -2
> 
> ১ম ক্ষেত্র (a = 5):
> (x + 2) / (x - 2) = 5
> বা, x + 2 = 5(x - 2) = 5x - 10
> বা, 5x - x = 2 + 10
> বা, 4x = 12
> বা, x = 3
> 
> ২য় ক্ষেত্র (a = -2):
> (x + 2) / (x - 2) = -2
> বা, x + 2 = -2(x - 2) = -2x + 4
> বা, x + 2x = 4 - 2
> বা, 3x = 2
> বা, x = 2/3
> 🎯 **উত্তর:** x = 3 অথবা x = 2/3

