# ৬ষ্ঠ অধ্যায়: রেখা, কোণ ও ত্রিভুজ

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*ইউক্লিডের জ্যামিতির স্বতঃসিদ্ধ, সমান্তরাল সরলরেখা ও ছেদকের কোণ, ত্রিভুজের সর্বসমতা এবং তিন কোণের সমষ্টি দুই সমকোণ উপপাদ্য।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> জ্যামিতিক স্বতঃসিদ্ধ ও প্রতিজ্ঞা ব্যাখ্যা করতে পারব;
> একান্তর কোণ, অনুরূপ কোণ ও অন্তঃস্থ কোণের সম্পর্ক প্রমাণ করতে পারব;
> ত্রিভুজের সর্বসমতার চার শর্ত প্রয়োগ করতে পারব;
> ত্রিভুজের কোণ ও বাহু সম্পর্কিত উপপাদ্যসমূহ প্রমাণ করতে পারব।

### 🔹 বিষয়: রেখা, কোণ ও ছেদকের বৈশিষ্ট্য
১. সন্নিহিত কোণ: দুটি কোণের একই শীর্ষবিন্দু এবং একটি সাধারণ বাহু থাকলে কোণ দুটিকে সন্নিহিত কোণ বলে।
২. বিপ্রতীপ কোণ: দুটি সরলরেখা পরস্পর ছেদ করলে যে চারটি কোণ উৎপন্ন হয়, তাদের বিপরীত কোণজোড়াকে বিপ্রতীপ কোণ বলে (বিপ্রতীপ কোণদ্বয় পরস্পর সমান)।
৩. সমান্তরাল রেখা ও ছেদক:
- অনুরূপ কোণগুলো পরস্পর সমান।
- একান্তর কোণগুলো পরস্পর সমান।
- ছেদকের একই পাশের অন্তঃস্থ কোণ দুটির সমষ্টি দুই সমকোণ (১৮০°)।

### 🔹 বিষয়: ত্রিভুজের সর্বসমতা (Congruence of Triangles)
দুটি ত্রিভুজ সর্বসম হওয়ার চারটি মৌলিক শর্ত:
১. বাহু-বাহু-বাহু (SSS): একটির তিন বাহু অপরটির তিন বাহুর সমান।
২. বাহু-কোণ-বাহু (SAS): একটির দুই বাহু ও অন্তর্ভুক্ত কোণ অপরটির অনুরূপ দুই বাহু ও অন্তর্ভুক্ত কোণের সমান।
৩. কোণ-বাহু-কোণ (ASA): একটির দুই কোণ ও সংলগ্ন বাহু অপরটির অনুরূপ দুই কোণ ও সংলগ্ন বাহুর সমান।
৪. সমকোণী ত্রিভুজের অতিভুজ-বাহু (RHS): একটির অতিভুজ ও এক বাহু অপরটির অতিভুজ ও এক বাহুর সমান।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ৬.৩ • উপপাদ্য ১৫: প্রমাণ কর যে, ত্রিভুজের যেকোনো দুই বাহুর দৈর্ঘ্যের সমষ্টি এর তৃতীয় বাহুর দৈর্ঘ্য অপেক্ষা বৃহত্তর।**
> 💡 **সমাধান:**
> **সাধারণ নির্বচন:** প্রমাণ করতে হবে যে, ত্রিভুজের যেকোনো দুই বাহুর সমষ্টি এর তৃতীয় বাহু অপেক্ষা বৃহত্তর।
> **বিশেষ নির্বচন:** মনে করি, ΔABC একটি ত্রিভুজ। প্রমাণ করতে হবে যে, AB + AC > BC।
> **অঙ্কন:** BA বাহুকে D পর্যন্ত এমনভাবে বর্ধিত করি যেন AD = AC হয়। C, D যোগ করি।
> **প্রমাণ:**
> ১. ΔACD-এ AD = AC (অঙ্কনানুসারে)।
> সুতরাং, ∠ACD = ∠ADC।
> ২. এখন, ∠BCD = ∠BCA + ∠ACD > ∠ACD
> বা, ∠BCD > ∠ADC (বা ∠BDC)।
> ৩. এখন ΔBCD-এ ∠BCD > ∠BDC।
> আমরা জানি, বৃহত্তর কোণের বিপরীত বাহু বৃহত্তর।
> সুতরাং, BD > BC
> বা, BA + AD > BC
> যেহেতু AD = AC, তাই:
> AB + AC > BC
> 🎯 **প্রমাণিত।**

> 🔢 **অনুশীলনী ৬.৩ • প্রশ্ন ১০: প্রমাণ কর যে, সমবাহু ত্রিভুজের মধ্যমাত্রয় পরস্পর সমান।**
> 💡 **সমাধান:**
> **বিশেষ নির্বচন:** মনে করি, ΔABC একটি সমবাহু ত্রিভুজ। অর্থাৎ AB = BC = CA। AD, BE এবং CF হলো যথাক্রমে BC, CA এবং AB বাহুর মধ্যমা।
> প্রমাণ করতে হবে যে, AD = BE = CF।
> 
> **প্রমাণ:**
> যেহেতু D এবং E যথাক্রমে BC এবং AC এর মধ্যবিন্দু,
> BD = 1/2 BC এবং AE = 1/2 AC।
> যেহেতু BC = AC, তাই BD = AE।
> এখন ΔABD এবং ΔBAE এর মধ্যে:
> - AB = AB (সাধারণ বাহু)
> - BD = AE (প্রমাণিত)
> - অন্তর্ভুক্ত ∠B = অন্তর্ভুক্ত ∠A (সমবাহু ত্রিভুজের সকল কোণ সমান = ৬০°)
> সুতরাং, বাহু-কোণ-বাহু (SAS) উপপাদ্যানুসারে,
> ΔABD ≅ ΔBAE
> অতএব, AD = BE।
> অনুরূপভাবে প্রমাণ করা যায় যে, BE = CF।
> সুতরাং, AD = BE = CF।
> 🎯 **প্রমাণিত:** সমবাহু ত্রিভুজের মধ্যমাত্রয় পরস্পর সমান।

