# ৭ম অধ্যায়: ব্যবহারিক জ্যামিতি

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*ত্রিভুজ অঙ্কন (ভূমি, সংলগ্ন কোণ ও দুই বাহুর সমষ্টি বা অন্তর), চতুর্ভুজ অঙ্কন এবং ট্রাপিজিয়াম গঠন।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> নির্দিষ্ট উপাত্ত দিয়ে ত্রিভুজ নিখুঁতভাবে অঙ্কন করতে পারব;
> ভূমি সংলগ্ন কোণ ও পরিসীমা দেওয়া থাকলে ত্রিভুজ গঠন করতে পারব;
> বিভিন্ন শর্তে চতুর্ভুজ ও ট্রাপিজিয়াম আঁকতে পারব।

### 🔹 বিষয়: ত্রিভুজ ও চতুর্ভুজ অঙ্কনের মৌলিক শর্ত
১. ত্রিভুজ অঙ্কনের জন্য ৩টি নিরপেক্ষ উপাত্ত প্রয়োজন (যেমন: তিন বাহু; দুই বাহু ও অন্তর্ভুক্ত কোণ; দুই কোণ ও এক বাহু)।
২. চতুর্ভুজ অঙ্কনের জন্য ৫টি নিরপেক্ষ উপাত্ত প্রয়োজন। তবে বিশেষ চতুর্ভুজের ক্ষেত্রে:
- সামান্তরিক: ৩টি উপাত্ত (যেমন দুই সন্নিহিত বাহু ও অন্তর্ভুক্ত কোণ)।
- রম্বস: ২টি উপাত্ত (বাহু ও একটি কোণ বা দুটি কর্ণ)।
- আয়ত: ২টি উপাত্ত (দুই সন্নিহিত বাহু)।
- বর্গ: ১টি উপাত্ত (এক বাহুর দৈর্ঘ্য)।

### 🔹 বিষয়: পাঠ্যবইয়ের গুরুত্বপূর্ণ সম্পাদ্যসমূহ
- সম্পাদ্য ১: ত্রিভুজের ভূমি, ভূমি সংলগ্ন একটি কোণ ও অপর দুই বাহুর সমষ্টি দেওয়া আছে। ত্রিভুজটি আঁকতে হবে।
- সম্পাদ্য ২: ত্রিভুজের ভূমি, ভূমি সংলগ্ন একটি সূক্ষ্মকোণ ও অপর দুই বাহুর অন্তর দেওয়া আছে। ত্রিভুজটি আঁকতে হবে।
- সম্পাদ্য ৩: ত্রিভুজের ভূমি সংলগ্ন দুটি কোণ ও পরিসীমা দেওয়া আছে। ত্রিভুজটি আঁকতে হবে।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ৭.১ • সম্পাদ্য ১: কোনো ত্রিভুজের ভূমি a = 5 cm, ভূমি সংলগ্ন কোণ ∠x = 60° এবং অপর দুই বাহুর সমষ্টি s = 8 cm দেওয়া আছে। ত্রিভুজটি অঙ্কন কর।**
> 💡 **সমাধান:**
> **অঙ্কনের বিবরণ:**
> ১. যেকোনো রশ্মি BE থেকে ভূমি a = 5 cm এর সমান করে BC রেখাংশ কেটে নিই।
> ২. BC রেখাংশের B বিন্দুতে ∠x = 60° এর সমান করে ∠CBF আঁকি।
> ৩. BF রশ্মি থেকে অপর দুই বাহুর সমষ্টি s = 8 cm এর সমান করে BD রেখাংশ কাটি।
> ৪. C, D যোগ করি।
> ৫. C বিন্দুতে DC রেখাংশের যে পাশে B বিন্দু আছে, সে পাশে ∠BDC এর সমান করে ∠DCA আঁকি।
> ৬. CA রেখাংশ BD কে A বিন্দুতে ছেদ করে।
> তাহলে, ΔABC-ই উদ্দিষ্ট ত্রিভুজ।
> 🎯 **প্রমাণ:** অঙ্কনানুসারে ∠ADC = ∠ACD, সুতরাং AD = AC।
> অতএব, BA + AC = BA + AD = BD = s। এবং BC = a, ∠ABC = ∠x।

> 🔢 **অনুশীলনী ৭.২ • প্রশ্ন ১৫: একটি রম্বসের দুটি কর্ণের দৈর্ঘ্য যথাক্রমে 6 cm এবং 8 cm দেওয়া আছে। রম্বসটি অঙ্কন কর।**
> 💡 **সমাধান:**
> **অঙ্কনের বিবরণ:**
> ১. যেকোনো রশ্মি AX থেকে ১ম কর্ণ d₁ = 8 cm এর সমান করে AC রেখাংশ কেটে নিই।
> ২. AC এর লম্বসমদ্বিখণ্ডক MN আঁকি যা AC কে O বিন্দুতে ছেদ করে।
> ৩. O বিন্দুতে d₂ = 6 cm এর অর্ধেক = 3 cm এর সমান ব্যাসার্ধ নিয়ে MN এর উভয়পাশে দুটি বৃত্তচাপ আঁকি যা MN কে যথাক্রমে B ও D বিন্দুতে ছেদ করে।
> ৪. A, B; B, C; C, D এবং D, A যোগ করি।
> তাহলে, ABCD-ই উদ্দিষ্ট রম্বস।
> 🎯 **প্রমাণ:** যেহেতু রম্বসের কর্ণদ্বয় পরস্পরকে সমকোণে সমদ্বিখণ্ডিত করে, ABCD একটি সঠিক রম্বস।

