    VALUES (v_chapter_id, $tag_math_ch08$
# ৮ম অধ্যায়: বৃত্ত

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*বৃত্তের জ্যা ও কেন্দ্রস্থ লম্ব, বৃত্তস্থ কোণ ও কেন্দ্রস্থ কোণের দ্বিগুণ সম্পর্ক, বৃত্তীয় চতুর্ভুজ এবং স্পর্শক উপপাদ্য।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> বৃত্তের জ্যা ও ব্যাসের সম্পর্ক উপপাদ্যের সাহায্যে প্রমাণ করতে পারব;
> একই চাপের উপর দণ্ডায়মান কেন্দ্রস্থ কোণ বৃত্তস্থ কোণের দ্বিগুণ প্রমাণ করতে পারব;
> অর্ধবৃত্তস্থ কোণ এক সমকোণ প্রমাণ করতে পারব;
> বৃত্তের স্পর্শক ও স্পর্শবিন্দুগামী ব্যাসার্ধের লম্ব সম্পর্ক ব্যাখ্যা করতে পারব।

### 🔹 বিষয়: বৃত্ত সম্পর্কিত গুরুত্বপূর্ণ উপপাদ্যসমূহ
১. উপপাদ্য ১৭: বৃত্তের কেন্দ্র ও ব্যাস ভিন্ন কোনো জ্যা-এর মধ্যবিন্দুর সংযোজক রেখাংশ ঐ জ্যা-এর উপর লম্ব।
২. উপপাদ্য ২০: বৃত্তের একই চাপের উপর দণ্ডায়মান কেন্দ্রস্থ কোণ বৃত্তস্থ কোণের দ্বিগুণ (বা বৃত্তস্থ কোণ কেন্দ্রস্থ কোণের অর্ধেক)।
৩. উপপাদ্য ২১: বৃত্তের একই চাপের উপর দণ্ডায়মান বৃত্তস্থ কোণগুলো পরস্পর সমান।
৪. উপপাদ্য ২২: অর্ধবৃত্তস্থ কোণ এক সমকোণ (৯০°)।
৫. উপপাদ্য ২৩: বৃত্তে অন্তর্লিখিত চতুর্ভুজের যেকোনো দুটি বিপরীত কোণের সমষ্টি দুই সমকোণ (১৮০°)।

### 🔹 বিষয়: বৃত্তের স্পর্শক (Tangents to a Circle)
- স্পর্শক হলো এমন একটি সরলরেখা যা বৃত্তকে কেবল একটি বিন্দুতে স্পর্শ করে।
- উপপাদ্য ২৫: বৃত্তের যেকোনো বিন্দুতে অঙ্কিত স্পর্শক স্পর্শবিন্দুগামী ব্যাসার্ধের উপর লম্ব।
- উপপাদ্য ২৬: বৃত্তের বহিঃস্থ কোনো বিন্দু থেকে বৃত্তে দুটি স্পর্শক টানলে, ঐ বিন্দু থেকে স্পর্শবিন্দুদ্বয়ের দূরত্ব সমান।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ৮.২ • উপপাদ্য ২০: প্রমাণ কর যে, বৃত্তের একই চাপের উপর দণ্ডায়মান কেন্দ্রস্থ কোণ বৃত্তস্থ কোণের দ্বিগুণ।**
> 💡 **সমাধান:**
> **বিশেষ নির্বচন:** মনে করি, O কেন্দ্রবিশিষ্ট একটি বৃত্তে BC চাপের উপর দণ্ডায়মান কেন্দ্রস্থ কোণ ∠BOC এবং বৃত্তস্থ কোণ ∠BAC।
> প্রমাণ করতে হবে যে, ∠BOC = 2∠BAC।
> 
> **অঙ্কন:** মনে করি, AC রেখাংশ কেন্দ্রগামী নয়। এ ক্ষেত্রে A বিন্দু দিয়ে কেন্দ্রগামী রেখাংশ AD আঁকি।
> 
> **প্রমাণ:**
> ১. ΔAOB-এ OA = OB (একই বৃত্তের ব্যাসার্ধ)।
> সুতরাং, ∠OAB = ∠OBA।
> ২. ΔAOB এর বহিঃস্থ কোণ ∠BOD = অন্তঃস্থ বিপরীত কোণদ্বয়ের সমষ্টি
> = ∠OAB + ∠OBA
> = ∠OAB + ∠OAB (যেহেতু ∠OBA = ∠OAB)
> = 2∠OAB ... (১)
> ৩. একইভাবে ΔAOC থেকে পাই,
> বহিঃস্থ ∠COD = 2∠OAC ... (২)
> ৪. (১) ও (২) সমীকরণ যোগ করে পাই:
> ∠BOD + ∠COD = 2∠OAB + 2∠OAC
> বা, ∠BOC = 2(∠OAB + ∠OAC)
> বা, ∠BOC = 2∠BAC।
> 🎯 **প্রমাণিত:** কেন্দ্রস্থ কোণ বৃত্তস্থ কোণের দ্বিগুণ।

> 🔢 **অনুশীলনী ৮.৩ • উপপাদ্য ২২: প্রমাণ কর যে, অর্ধবৃত্তস্থ কোণ এক সমকোণ।**
> 💡 **সমাধান:**
> **বিশেষ নির্বচন:** মনে করি, O কেন্দ্রবিশিষ্ট বৃত্তে AB একটি ব্যাস এবং ∠ACB একটি অর্ধবৃত্তস্থ কোণ।
> প্রমাণ করতে হবে যে, ∠ACB = এক সমকোণ (৯০°)।
> 
> **প্রমাণ:**
> AB ব্যাসের বিপরীত দিকে বৃত্তের উপর একটি বিন্দু D নিই।
> তাহলে ADB চাপের উপর দণ্ডায়মান কেন্দ্রস্থ কোণ সরলকোণ ∠AOB এবং বৃত্তস্থ কোণ ∠ACB।
> আমরা জানি, কেন্দ্রস্থ কোণ বৃত্তস্থ কোণের দ্বিগুণ।
> অর্থাৎ, 2∠ACB = সরলকোণ ∠AOB
> যেহেতু সরলকোণ ∠AOB = দুই সমকোণ (১৮০°),
> সুতরাং, 2∠ACB = দুই সমকোণ
> বা, ∠ACB = (দুই সমকোণ) / 2 = এক সমকোণ (৯০°)।
> 🎯 **প্রমাণিত:** অর্ধবৃত্তস্থ কোণ এক সমকোণ।

$tag_math_ch08$, 1);

