# ৯ম অধ্যায়: ত্রিকোণমিতিক অনুপাত

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*সমকোণী ত্রিভুজের সূক্ষ্মকোণের ত্রিকোণমিতিক অনুপাত, মৌলিক ত্রিকোণমিতিক অভেদাবলি এবং ০°, ৩০°, ৪৫°, ৬০°, ৯০° কোণের মান নির্ণয়।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> সমকোণী ত্রিভুজের বাহুগুলোর অনুপাত হিসেবে sin, cos, tan, cot, sec, cosec সংজ্ঞায়িত করতে পারব;
> ত্রিকোণমিতিক অভেদাবলি (sin²θ + cos²θ = 1 ইত্যাদি) প্রমাণ ও প্রয়োগ করতে পারব;
> নির্দিষ্ট সূক্ষ্মকোণের ত্রিকোণমিতিক মান নির্ণয় করতে পারব;
> ত্রিকোণমিতিক সমীকরণ সমাধান করতে পারব।

### 🔹 বিষয়: ত্রিকোণমিতিক অনুপাত ও মৌলিক অভেদাবলি
সমকোণী ত্রিভুজে সূক্ষ্মকোণ θ এর সাপেক্ষে:
- sin θ = লম্ব / অতিভুজ
- cos θ = ভূমি / অতিভুজ
- tan θ = লম্ব / ভূমি = sin θ / cos θ
- cot θ = ভূমি / লম্ব = cos θ / sin θ = 1 / tan θ
- sec θ = অতিভুজ / ভূমি = 1 / cos θ
- cosec θ = অতিভুজ / লম্ব = 1 / sin θ

মৌলিক অভেদাবলি:
১. sin²θ + cos²θ = 1 ⇒ sin²θ = 1 - cos²θ, cos²θ = 1 - sin²θ
২. sec²θ - tan²θ = 1 ⇒ sec²θ = 1 + tan²θ, tan²θ = sec²θ - 1
৩. cosec²θ - cot²θ = 1 ⇒ cosec²θ = 1 + cot²θ, cot²θ = cosec²θ - 1

### 🔹 বিষয়: আদর্শ কোণসমূহের ত্রিকোণমিতিক মান
- sin 0° = 0, sin 30° = 1/2, sin 45° = 1/√(2), sin 60° = √(3)/2, sin 90° = 1
- cos 0° = 1, cos 30° = √(3)/2, cos 45° = 1/√(2), cos 60° = 1/2, cos 90° = 0
- tan 0° = 0, tan 30° = 1/√(3), tan 45° = 1, tan 60° = √(3), tan 90° = অসংজ্ঞায়িত

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ৯.১ • প্রশ্ন ১৯: প্রমাণ কর যে, √((1 - sin A) / (1 + sin A)) = sec A - tan A**
> 💡 **সমাধান:**
> **প্রমাণ:**
> বামপক্ষ (LHS) = √((1 - sin A) / (1 + sin A))
> লব ও হরকে √(1 - sin A) দ্বারা গুণ করে পাই:
> = √(((1 - sin A)(1 - sin A)) / ((1 + sin A)(1 - sin A)))
> = √((1 - sin A)² / (1 - sin²A))
> 
> আমরা জানি, 1 - sin²A = cos²A
> = √((1 - sin A)² / cos²A)
> বর্গমূল তুলে পাই:
> = (1 - sin A) / cos A
> আলাদা করে ভাগ করি:
> = (1 / cos A) - (sin A / cos A)
> = sec A - tan A
> = ডানপক্ষ (RHS)
> 🎯 **প্রমাণিত:** √((1 - sin A) / (1 + sin A)) = sec A - tan A।

> 🔢 **অনুশীলনী ৯.১ • প্রশ্ন ২১: cos A + sin A = √(2) cos A হলে, প্রমাণ কর যে, cos A - sin A = √(2) sin A।**
> 💡 **সমাধান:**
> **প্রমাণ:**
> দেওয়া আছে,
> cos A + sin A = √(2) cos A
> পক্ষান্তর করে পাই:
> sin A = √(2) cos A - cos A
> বা, sin A = (√(2) - 1) cos A
> উভয়পক্ষকে (√(2) + 1) দ্বারা গুণ করে পাই:
> (√(2) + 1) sin A = (√(2) + 1)(√(2) - 1) cos A
> বা, √(2) sin A + sin A = {(√(2))² - 1²} cos A
> বা, √(2) sin A + sin A = (2 - 1) cos A
> বা, √(2) sin A + sin A = cos A
> বা, cos A - sin A = √(2) sin A
> 🎯 **প্রমাণিত।**

> 🔢 **অনুশীলনী ৯.২ • প্রশ্ন ২৪: সমাধান কর (0° < θ < 90°): cos²θ - sin²θ = 2 - 5 cos θ**
> 💡 **সমাধান:**
> **সমাধান:**
> প্রদত্ত সমীকরণ: cos²θ - sin²θ = 2 - 5 cos θ
> আমরা জানি, sin²θ = 1 - cos²θ
> মান বসিয়ে পাই:
> cos²θ - (1 - cos²θ) = 2 - 5 cos θ
> বা, cos²θ - 1 + cos²θ = 2 - 5 cos θ
> বা, 2 cos²θ - 1 = 2 - 5 cos θ
> পক্ষান্তর করে পাই:
> 2 cos²θ + 5 cos θ - 3 = 0
> মধ্যপদ বিভাজন করি:
> 2 cos²θ + 6 cos θ - cos θ - 3 = 0
> বা, 2 cos θ(cos θ + 3) - 1(cos θ + 3) = 0
> বা, (cos θ + 3)(2 cos θ - 1) = 0
> 
> যেহেতু cos θ এর মান কখনোই -3 হতে পারে না (কারণ -1 ≤ cos θ ≤ 1),
> সুতরাং, cos θ + 3 ≠ 0।
> 
> অতএব,
> 2 cos θ - 1 = 0
> বা, 2 cos θ = 1
> বা, cos θ = 1/2
> বা, cos θ = cos 60°
> বা, θ = 60°
> 🎯 **উত্তর:** θ = 60°

$tag_math_ch09$, 1);

