# ১০ম অধ্যায়: দূরত্ব ও উচ্চতা

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*উন্নতি কোণ ও অবনতি কোণ, সমকোণী ত্রিভুজ অঙ্কন এবং ত্রিকোণমিতির সাহায্যে দুর্গম দূরত্ব, নদীর বিস্তার ও মিনারের উচ্চতা নির্ণয়।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> উন্নতি কোণ ও অবনতি কোণ চিহ্নিত করতে পারব;
> ত্রিকোণমিতির সাহায্যে বাস্তব জীবনের দূরত্ব ও উচ্চতার চিত্রাঙ্কন করতে পারব;
> নদীর বিস্তার, মিনারের উচ্চতা এবং খুঁটি ভাঙার সমস্যা সমাধান করতে পারব।

### 🔹 বিষয়: উন্নতি কোণ ও অবনতি কোণ (Elevation & Depression Angles)
১. উন্নতি কোণ (Angle of Elevation): ভূতলের সমান্তরাল রেখার উপরের কোনো বিন্দু ভূমির সমান্তরাল রেখার সাথে যে কোণ উৎপন্ন করে, তাকে উন্নতি কোণ বলে।
২. অবনতি কোণ (Angle of Depression): ভূতলের সমান্তরাল রেখার নিচের কোনো বিন্দু ভূমির সমান্তরাল রেখার সাথে যে কোণ উৎপন্ন করে, তাকে অবনতি কোণ বলে।
- অবনতি কোণ ও সংশ্লিষ্ট উন্নতি কোণ পরস্পর একান্তর কোণ হওয়ায় এরা পরস্পর সমান।

### 🔹 বিষয়: দূরত্ব ও উচ্চতার সমস্যা সমাধানের মূল কৌশল
১. ৩০° কোণের ক্ষেত্রে: ভূমি > লম্ব (ভূমি লম্বের চেয়ে বড় হবে)।
২. ৪৫° কোণের ক্ষেত্রে: লম্ব = ভূমি।
৩. ৬০° কোণের ক্ষেত্রে: লম্ব > ভূমি (লম্ব ভূমির চেয়ে বড় হবে)।
প্রয়োজনীয় ত্রিকোণমিতিক অনুপাত:
- লম্ব ও ভূমি সম্পর্কিত হলে: tan θ = লম্ব / ভূমি
- লম্ব ও অতিভুজ সম্পর্কিত হলে: sin θ = লম্ব / অতিভুজ

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১০ • প্রশ্ন ১০: একটি মিনারের পাদদেশ থেকে কিছু দূরে একটি স্থানে মিনারের শীর্ষের উন্নতি কোণ 60° এবং মিনারটির উচ্চতা 26 মিটার হলে, মিনারটি থেকে স্থানটির দূরত্ব কত?**
> 💡 **সমাধান:**
> **সমাধান:**
> মনে করি, মিনারের উচ্চতা AB = 26 মিটার।
> মিনারটির পাদদেশ B থেকে স্থানটির দূরত্ব BC = x মিটার।
> C বিন্দুতে মিনারের শীর্ষের উন্নতি কোণ ∠ACB = 60°।
> 
> সমকোণী ত্রিভুজ ΔABC হতে পাই:
> tan ∠ACB = AB / BC
> বা, tan 60° = 26 / x
> আমরা জানি, tan 60° = √(3)
> বা, √(3) = 26 / x
> বা, x = 26 / √(3)
> লব ও হরকে √(3) দ্বারা গুণ করি:
> বা, x = (26 · √(3)) / 3 ≈ (26 · 1.73205) / 3 ≈ 45.033 / 3 ≈ 15.011 মিটার।
> 🎯 **উত্তর:** স্থানটির দূরত্ব প্রায় 15.011 মিটার (বা 26/√(3) মিটার)।

> 🔢 **অনুশীলনী ১০ • প্রশ্ন ১৪: একটি নদীর তীরে কোনো এক স্থানে দাঁড়িয়ে এক ব্যক্তি দেখল যে, ঠিক বিপরীত তীরে অবস্থিত একটি টাওয়ারের উন্নতি কোণ 60°। ওই স্থান থেকে 32 মিটার পিছিয়ে গেলে টাওয়ারের উন্নতি কোণ 30° হয়। টাওয়ারের উচ্চতা এবং নদীর বিস্তার নির্ণয় কর।**
> 💡 **সমাধান:**
> **সমাধান:**
> মনে করি, টাওয়ারের উচ্চতা AB = h মিটার।
> নদীর বিস্তার BC = x মিটার।
> C বিন্দুতে উন্নতি কোণ ∠ACB = 60°।
> C থেকে 32 মিটার পিছিয়ে D বিন্দুতে গেলে CD = 32 মিটার এবং ∠ADB = 30°।
> সুতরাং, BD = BC + CD = x + 32 মিটার।
> 
> **ধাপ ১: সমকোণী ত্রিভুজ ΔABC হতে:**
> tan 60° = AB / BC
> বা, √(3) = h / x
> বা, h = x · √(3) ... (১)
> 
> **ধাপ ২: সমকোণী ত্রিভুজ ΔABD হতে:**
> tan 30° = AB / BD
> বা, 1 / √(3) = h / (x + 32)
> বা, h · √(3) = x + 32
> 
> **ধাপ ৩: (১) নং সমীকরণ থেকে h এর মান বসাই:**
> (x · √(3)) · √(3) = x + 32
> বা, 3x = x + 32
> বা, 3x - x = 32
> বা, 2x = 32
> বা, x = 16 মিটার।
> 
> **ধাপ ৪: টাওয়ারের উচ্চতা h নির্ণয়:**
> h = x · √(3) = 16 · √(3) ≈ 16 · 1.732 = 27.713 মিটার।
> 🎯 **উত্তর:** টাওয়ারের উচ্চতা প্রায় 27.713 মিটার এবং নদীর বিস্তার 16 মিটার।

> 🔢 **অনুশীলনী ১০ • প্রশ্ন ১৭: 64 মিটার দীর্ঘ একটি খুঁটি ভেঙে গিয়ে সম্পূর্ণ বিচ্ছিন্ন না হয়ে ভূমির সাথে 60° কোণ উৎপন্ন করে। খুঁটিটির ভাঙা অংশের দৈর্ঘ্য নির্ণয় কর।**
> 💡 **সমাধান:**
> **সমাধান:**
> মনে করি, সম্পূর্ণ খুঁটির দৈর্ঘ্য AB = 64 মিটার।
> খুঁটিটি C বিন্দুতে h উচ্চতায় ভেঙে গিয়ে তার ভাঙা অংশ AC বিচ্ছিন্ন না হয়ে ভূমির সাথে D বিন্দুতে মিলিত হয়।
> সুতরাং, ভাঙা অংশের দৈর্ঘ্য AC = CD = 64 - h মিটার।
> ভূমিতে উৎপন্ন কোণ ∠BDC = 60° এবং দণ্ডায়মান অংশ BC = h মিটার।
> 
> সমকোণী ত্রিভুজ ΔBCD হতে পাই:
> sin ∠BDC = লম্ব / অতিভুজ = BC / CD
> বা, sin 60° = h / (64 - h)
> আমরা জানি, sin 60° = √(3) / 2
> বা, √(3) / 2 = h / (64 - h)
> বা, 2h = √(3)(64 - h) = 64√(3) - h√(3)
> বা, 2h + h√(3) = 64√(3)
> বা, h(2 + √(3)) = 64 · 1.732 = 110.85
> বা, h = 110.85 / (2 + 1.732) = 110.85 / 3.732 ≈ 29.70 মিটার।
> 
> অতএব, ভাঙা অংশের দৈর্ঘ্য CD = 64 - h = 64 - 29.70 = 34.30 মিটার (প্রায়)।
> 🎯 **উত্তর:** ভাঙা অংশের দৈর্ঘ্য প্রায় 34.30 মিটার।

