# ১১শ অধ্যায়: বীজগাণিতিক অনুপাত ও সমানুপাত

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*অনুপাত ও সমানুপাতের রূপান্তর, একান্তরকরণ, ব্যস্তকরণ, যোজন, বিয়োজন, যোজন-বিয়োজন এবং বাস্তবভিত্তিক সমস্যা সমাধান।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> বীজগাণিতিক অনুপাত ও সমানুপাতের ধর্মাবলি ব্যাখ্যা করতে পারব;
> যোজন-বিয়োজন ও একান্তরকরণ প্রক্রিয়া প্রয়োগ করে সমীকরণ সমাধান করতে পারব;
> ধারাবাহিক অনুপাত ও বাস্তবভিত্তিক সমানুপাতিক সমস্যা সমাধান করতে পারব।

### 🔹 বিষয়: অনুপাত ও সমানুপাতের মৌলিক ধর্মাবলি
যদি a : b = c : d হয়, তবে:
১. ব্যস্তকরণ (Invertendo): b : a = d : c (বা b/a = d/c)
২. একান্তরকরণ (Alternando): a : c = b : d (বা a/c = b/d)
৩. যোজন (Componendo): (a + b) / b = (c + d) / d
৪. বিয়োজন (Dividendo): (a - b) / b = (c - d) / d
৫. যোজন-বিয়োজন (Componendo-Dividendo): (a + b) / (a - b) = (c + d) / (c - d)
৬. ক্রমিক সমানুপাতী: a, b, c ক্রমিক সমানুপাতী হলে a/b = b/c ⇒ b² = ac।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১১.১ • প্রশ্ন ৭(ক): যদি a : b = b : c হয়, তবে প্রমাণ কর যে, a / c = (a² + b²) / (b² + c²)**
> 💡 **সমাধান:**
> **প্রমাণ:**
> দেওয়া আছে, a : b = b : c
> বা, a / b = b / c = k (ধরি)
> সুতরাং, b = ck এবং a = bk = (ck)k = ck²।
> 
> বামপক্ষ (LHS) = a / c
> মান বসাই:
> = (ck²) / c = k²
> 
> ডানপক্ষ (RHS) = (a² + b²) / (b² + c²)
> মান বসাই:
> = ((ck²)² + (ck)²) / ((ck)² + c²)
> = (c²k⁴ + c²k²) / (c²k² + c²)
> = c²k²(k² + 1) / c²(k² + 1)
> = k²
> যেহেতু LHS = RHS = k²,
> 🎯 **প্রমাণিত:** a / c = (a² + b²) / (b² + c²)।

> 🔢 **অনুশীলনী ১১.১ • প্রশ্ন ১০: যদি x = 4ab / (a + b) হয়, তবে দেখাও যে, (x + 2a) / (x - 2a) + (x + 2b) / (x - 2b) = 2**
> 💡 **সমাধান:**
> **প্রমাণ:**
> দেওয়া আছে, x = 4ab / (a + b)
> 
> ১ম অংশ: x = (2a · 2b) / (a + b)
> বা, x / 2a = 2b / (a + b)
> যোজন-বিয়োজন করে পাই:
> (x + 2a) / (x - 2a) = (2b + a + b) / (2b - a - b)
> বা, (x + 2a) / (x - 2a) = (a + 3b) / (b - a) ... (১)
> 
> ২য় অংশ: x / 2b = 2a / (a + b)
> যোজন-বিয়োজন করে পাই:
> (x + 2b) / (x - 2b) = (2a + a + b) / (2a - a - b)
> বা, (x + 2b) / (x - 2b) = (3a + b) / (a - b) = -(3a + b) / (b - a) ... (২)
> 
> এখন (১) ও (২) যোগ করি:
> (x + 2a) / (x - 2a) + (x + 2b) / (x - 2b)
> = (a + 3b) / (b - a) - (3a + b) / (b - a)
> = (a + 3b - 3a - b) / (b - a)
> = (2b - 2a) / (b - a)
> = 2(b - a) / (b - a) = 2
> 🎯 **প্রমাণিত:** ফলাফল = 2।

> 🔢 **অনুশীলনী ১১.১ • প্রশ্ন ১৩: সমাধান কর: (1 - √(1 - x)) / (1 + √(1 - x)) = 1/3**
> 💡 **সমাধান:**
> **সমাধান:**
> যোজন-বিয়োজন করে পাই:
> {(1 - √(1 - x)) + (1 + √(1 - x))} / {(1 - √(1 - x)) - (1 + √(1 - x))} = (1 + 3) / (1 - 3)
> বা, (1 - √(1 - x) + 1 + √(1 - x)) / (1 - √(1 - x) - 1 - √(1 - x)) = 4 / (-2)
> বা, 2 / (-2√(1 - x)) = -2
> বা, -1 / √(1 - x) = -2
> বা, 1 / √(1 - x) = 2
> বা, √(1 - x) = 1/2
> উভয়পক্ষকে বর্গ করে পাই:
> 1 - x = 1/2² = 1/4
> বা, x = 1 - 1/4 = 3/4
> 🎯 **উত্তর:** x = 3/4

$tag_math_ch11$, 1);

