# ১২শ অধ্যায়: দুই চলকবিশিষ্ট সরল সহসমীকরণ

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*সহসমীকরণের সঙ্গতি ও নির্ভরতা যাচাই, সমাধান পদ্ধতি (প্রতিস্থাপন, অপনয়ন, বজ্রগুণন ও লেখচিত্র) এবং বাস্তবভিত্তিক সমস্যা।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> দুই চলকবিশিষ্ট সহসমীকরণের সঙ্গতি ও সমাধানের শর্ত ব্যাখ্যা করতে পারব;
> প্রতিস্থাপন, অপনয়ন ও বজ্রগুণন (Cross-multiplication) পদ্ধতিতে সমাধান করতে পারব;
> বাস্তবভিত্তিক সমস্যার সরল সহসমীকরণ গঠন ও সমাধান করতে পারব।

### 🔹 বিষয়: সহসমীকরণের সঙ্গতি ও সমাধানের শর্তাবলী
সমীকরণ জোড়: a₁x + b₁y = c₁ এবং a₂x + b₂y = c₂ এর জন্য:
১. a₁/a₂ ≠ b₁/b₂ হলে: সমীকরণ জোড় সঙ্গতিপূর্ণ, পরস্পর অনির্ভরশীল এবং এদের একটিমাত্র (অনন্য) সমাধান থাকবে।
২. a₁/a₂ = b₁/b₂ = c₁/c₂ হলে: সমীকরণ জোড় সঙ্গতিপূর্ণ, পরস্পর নির্ভরশীল এবং এদের অসংখ্য সমাধান থাকবে।
৩. a₁/a₂ = b₁/b₂ ≠ c₁/c₂ হলে: সমীকরণ জোড় অসঙ্গতিপূর্ণ, পরস্পর অনির্ভরশীল এবং এদের কোনো বাস্তব সমাধান নেই।

### 🔹 বিষয়: বজ্রগুণন (Cross-multiplication) সূত্র
যদি a₁x + b₁y + c₁ = 0 এবং a₂x + b₂y + c₂ = 0 হয়, তবে:
x / (b₁c₂ - b₂c₁) = y / (c₁a₂ - c₂a₁) = 1 / (a₁b₂ - a₂b₁)
অতএব:
- x = (b₁c₂ - b₂c₁) / (a₁b₂ - a₂b₁)
- y = (c₁a₂ - c₂a₁) / (a₁b₂ - a₂b₁)

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১২.২ • প্রশ্ন ৩ (প্রতিস্থাপন পদ্ধতি): সমাধান কর: 3x - 5y = -9 এবং 5x - 2y = 4**
> 💡 **সমাধান:**
> **সমাধান:**
> প্রদত্ত সমীকরণদ্বয়:
> 3x - 5y = -9 ... (১)
> 5x - 2y = 4 ... (২)
> 
> (২) নং সমীকরণ হতে পাই:
> 5x = 4 + 2y
> বা, x = (4 + 2y) / 5 ... (৩)
> 
> (১) নং সমীকরণে x এর মান বসাই:
> 3 · ((4 + 2y) / 5) - 5y = -9
> বা, (12 + 6y) / 5 - 5y = -9
> উভয়পক্ষকে 5 দ্বারা গুণ করে পাই:
> 12 + 6y - 25y = -45
> বা, 12 - 19y = -45
> বা, -19y = -45 - 12 = -57
> বা, y = -57 / (-19) = 3
> 
> এখন (৩) নং সমীকরণে y = 3 বসাই:
> x = (4 + 2 · 3) / 5 = (4 + 6) / 5 = 10 / 5 = 2
> 🎯 **উত্তর:** নির্ণেয় সমাধান (x, y) = (2, 3)

> 🔢 **অনুশীলনী ১২.২ • প্রশ্ন ৮ (অপনয়ন পদ্ধতি): সমাধান কর: ax - by = ab এবং bx - ay = ab**
> 💡 **সমাধান:**
> **সমাধান:**
> প্রদত্ত সমীকরণদ্বয়:
> ax - by = ab ... (১)
> bx - ay = ab ... (২)
> 
> (১) নং কে a দ্বারা এবং (২) নং কে b দ্বারা গুণ করে বিয়োগ করি:
>   a²x - aby = a²b
> - b²x - aby = ab²
> -----------------------
> (a² - b²)x = a²b - ab² = ab(a - b)
> 
> বা, (a + b)(a - b)x = ab(a - b)
> উভয়পক্ষকে (a - b) দ্বারা ভাগ করে পাই (যেহেতু a ≠ b):
> (a + b)x = ab
> বা, x = ab / (a + b)
> 
> অনুরূপভাবে (১) নং কে b দ্বারা এবং (২) নং কে a দ্বারা গুণ করে বিয়োগ করে পাই:
> y = -ab / (a + b)
> 🎯 **উত্তর:** (x, y) = (ab / (a + b), -ab / (a + b))

> 🔢 **অনুশীলনী ১২.২ • প্রশ্ন ১৫ (বজ্রগুণন পদ্ধতি): সমাধান কর: 6x - y = 1 এবং 3x + 2y = 13**
> 💡 **সমাধান:**
> **সমাধান:**
> সমীকরণদ্বয়কে আদর্শ রূপে সাজিয়ে পাই:
> 6x - y - 1 = 0 ... (১)
> 3x + 2y - 13 = 0 ... (২)
> 
> বজ্রগুণন সূত্র প্রয়োগ করি:
> x / ((-1)(-13) - (2)(-1)) = y / ((-1)(3) - (-13)(6)) = 1 / ((6)(2) - (3)(-1))
> বা, x / (13 + 2) = y / (-3 + 78) = 1 / (12 + 3)
> বা, x / 15 = y / 75 = 1 / 15
> 
> ১ম ও ৩য় অনুপাত হতে:
> x / 15 = 1 / 15
> বা, x = 1
> 
> ২য় ও ৩য় অনুপাত হতে:
> y / 75 = 1 / 15
> বা, y = 75 / 15 = 5
> 🎯 **উত্তর:** নির্ণেয় সমাধান (x, y) = (1, 5)

$tag_math_ch12$, 1);

