# ১৩শ অধ্যায়: সসীম ধারা

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*অনুক্রম ও ধারা, সমান্তর ধারা (n-তম পদ ও সমষ্টি সূত্র), গুণোত্তর ধারা (n-তম পদ ও সমষ্টি সূত্র) এবং স্বাভাবিক সংখ্যার সমষ্টি সূত্রাবলি।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> সমান্তর ধারা ও গুণোত্তর ধারার পার্থক্য ব্যাখ্যা করতে পারব;
> সমান্তর ধারার সাধারণ পদ এবং প্রথম n সংখ্যক পদের সমষ্টি নির্ণয় করতে পারব;
> গুণোত্তর ধারার n-তম পদ ও সমষ্টি নির্ণয় করতে পারব;
> প্রথম n সংখ্যক স্বাভাবিক সংখ্যার সমষ্টি, বর্গের সমষ্টি ও ঘনের সমষ্টির সূত্র প্রয়োগ করতে পারব।

### 🔹 বিষয়: সমান্তর ধারা (Arithmetic Progression)
যদি কোনো ধারার যেকোনো পদ ও তার পূর্ববর্তী পদের পার্থক্য সব সময় সমান হয়, তবে তাকে সমান্তর ধারা বলে।
- প্রথম পদ = a, সাধারণ অন্তর = d = (যেকোনো পদ - পূর্ববর্তী পদ)
১. n-তম পদ = a + (n - 1)d
২. প্রথম n সংখ্যক পদের সমষ্টি: Sₙ = n/2 · {2a + (n - 1)d}
৩. প্রথম n সংখ্যক স্বাভাবিক সংখ্যার সমষ্টি: 1 + 2 + 3 + ... + n = n(n + 1) / 2
৪. বর্গের সমষ্টি: 1² + 2² + ... + n² = n(n + 1)(2n + 1) / 6
৫. ঘনের সমষ্টি: 1³ + 2³ + ... + n³ = {n(n + 1) / 2}²

### 🔹 বিষয়: গুণোত্তর ধারা (Geometric Progression)
যদি কোনো ধারার যেকোনো পদ ও তার পূর্ববর্তী পদের অনুপাত সব সময় সমান হয়, তবে তাকে গুণোত্তর ধারা বলে।
- প্রথম পদ = a, সাধারণ অনুপাত = r = (যেকোনো পদ / পূর্ববর্তী পদ)
১. n-তম পদ = arⁿ⁻¹
২. প্রথম n সংখ্যক পদের সমষ্টি:
- যখন r > 1: Sₙ = a(rⁿ - 1) / (r - 1)
- যখন r < 1: Sₙ = a(1 - rⁿ) / (1 - r)

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১৩.১ • প্রশ্ন ৭: 4 + 7 + 10 + 13 + ... ধারাটির কোন পদ 301?**
> 💡 **সমাধান:**
> **সমাধান:**
> প্রদত্ত ধারাটির প্রথম পদ a = 4
> সাধারণ অন্তর d = 7 - 4 = 10 - 7 = 3
> যেহেতু যেকোনো পদ ও পূর্ববর্তী পদের অন্তর সব সময় সমান (= 3), তাই এটি একটি সমান্তর ধারা।
> 
> মনে করি, ধারাটির n-তম পদ = 301।
> আমরা জানি,
> n-তম পদ = a + (n - 1)d
> বা, 4 + (n - 1) · 3 = 301
> বা, 4 + 3n - 3 = 301
> বা, 3n + 1 = 301
> বা, 3n = 301 - 1 = 300
> বা, n = 300 / 3 = 100
> অতএব, ধারাটির ১০০-তম পদ 301।
> 🎯 **উত্তর:** 100-তম পদ

> 🔢 **অনুশীলনী ১৩.১ • প্রশ্ন ১১: 5 + 11 + 17 + 23 + ... + 59 = কত?**
> 💡 **সমাধান:**
> **সমাধান:**
> ধারাটির প্রথম পদ a = 5
> সাধারণ অন্তর d = 11 - 5 = 6 (সমান্তর ধারা)
> শেষ পদ (n-তম পদ) = 59
> 
> **ধাপ ১: পদ সংখ্যা n নির্ণয়:**
> a + (n - 1)d = 59
> বা, 5 + (n - 1) · 6 = 59
> বা, 6(n - 1) = 59 - 5 = 54
> বা, n - 1 = 54 / 6 = 9
> বা, n = 10
> 
> **ধাপ ২: সমষ্টি S₁₀ নির্ণয়:**
> আমরা জানি, Sₙ = n/2 · {2a + (n - 1)d}
> বা, S₁₀ = 10/2 · {2 · 5 + (10 - 1) · 6}
> = 5 · {10 + 9 · 6}
> = 5 · {10 + 54}
> = 5 · 64 = 320
> 🎯 **উত্তর:** 320

> 🔢 **অনুশীলনী ১৩.২ • প্রশ্ন ৮: একটি গুণোত্তর ধারার ৫ম পদ (2√(3)) / 9 এবং ১০ম পদ (8√(2)) / 81 হলে, ধারাটির ৩য় পদ কত?**
> 💡 **সমাধান:**
> **সমাধান:**
> মনে করি, গুণোত্তর ধারার প্রথম পদ = a এবং সাধারণ অনুপাত = r।
> আমরা জানি, n-তম পদ = arⁿ⁻¹
> 
> প্রশ্নমতে:
> ৫ম পদ = ar⁴ = (2√(3)) / 9 ... (১)
> ১০ম পদ = ar⁹ = (8√(2)) / 81 ... (২)
> 
> (২) নং কে (১) নং দ্বারা ভাগ করে পাই:
> (ar⁹) / (ar⁴) = {(8√(2)) / 81} / {(2√(3)) / 9}
> বা, r⁵ = ((8√(2)) / 81) × (9 / (2√(3)))
> = (4√(2)) / (9√(3))
> আমরা লিখতে পারি: 4 = (√(2))⁴ এবং 9 = (√(3))⁴
> সুতরাং, 4√(2) = (√(2))⁵ এবং 9√(3) = (√(3))⁵
> বা, r⁵ = (√(2) / √(3))⁵
> বা, r = √(2) / √(3)
> 
> এখন (১) নং সমীকরণে r এর মান বসাই:
> a · (√(2) / √(3))⁴ = (2√(3)) / 9
> বা, a · 4/9 = (2√(3)) / 9
> বা, 4a = 2√(3)
> বা, a = (2√(3)) / 4 = √(3) / 2
> 
> অতএব, ধারাটির ৩য় পদ = ar²
> = (√(3) / 2) · (√(2) / √(3))²
> = (√(3) / 2) · 2/3
> = √(3) / 3 = 1 / √(3)
> 🎯 **উত্তর:** ৩য় পদ = 1 / √(3)

$tag_math_ch13$, 1);

