# ১৪শ অধ্যায়: অনুপাত, সদৃশতা ও প্রতিসমতা

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*রেখাংশের অনুপাত, থেলেসের উপপাদ্য (সমান্তরাল রেখা দ্বারা বাহু বিভাজন), সদৃশকোণী ত্রিভুজ, প্রতিসমতার অক্ষ ও ঘূর্ণন প্রতিসমতা।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> জ্যামিতিক অনুপাত ও সমানুপাত ব্যাখ্যা করতে পারব;
> থেলেসের উপপাদ্য ও এর বিপরীত উপপাদ্য প্রমাণ করতে পারব;
> সদৃশ ত্রিভুজের অনুরূপ বাহু ও ক্ষেত্রফলের সম্পর্ক প্রয়োগ করতে পারব;
> রৈখিক প্রতিসমতা ও ঘূর্ণন প্রতিসমতা ব্যাখ্যা করতে পারব।

### 🔹 বিষয়: থেলেসের উপপাদ্য ও সদৃশতা (Thales Theorem & Similarity)
১. উপপাদ্য ২৮ (থেলেসের উপপাদ্য): ত্রিভুজের যেকোনো বাহুর সমান্তরাল সরলরেখা অপর বাহুদ্বয়কে বা তাদের বর্ধিতাংশকে সমান অনুপাতে বিভক্ত করে। অর্থাৎ, ΔABC-এ BC || DE হলে, AD/DB = AE/EC।
২. উপপাদ্য ৩০ (সদৃশকোণী ত্রিভুজ): দুটি ত্রিভুজ সদৃশকোণী হলে তাদের অনুরূপ বাহুগুলো সমানুপাতিক হয়।
৩. উপপাদ্য ৩২ (সদৃশ ত্রিভুজের ক্ষেত্রফল): দুটি সদৃশ ত্রিভুজের ক্ষেত্রফলের অনুপাত তাদের যেকোনো দুই অনুরূপ বাহুর উপর অঙ্কিত বর্গক্ষেত্রের ক্ষেত্রফলের অনুপাতের সমান।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১৪.১ • প্রশ্ন ৫: প্রমাণ কর যে, ত্রিভুজের কোনো কোণের সমদ্বিখণ্ডক বিপরীত বাহুকে ঐ কোণ সংলগ্ন বাহুদ্বয়ের অনুপাতে অন্তর্বিভক্ত করে।**
> 💡 **সমাধান:**
> **বিশেষ নির্বচন:** মনে করি, ΔABC এর ∠A এর সমদ্বিখণ্ডক AD রেখাংশ বিপরীত বাহু BC কে D বিন্দুতে ছেদ করে।
> প্রমাণ করতে হবে যে, BD : DC = AB : AC (বা BD/DC = AB/AC)।
> 
> **অঙ্কন:** C বিন্দু দিয়ে DA এর সমান্তরাল করে রেখা আঁকি যা বর্ধিত BA কে E বিন্দুতে ছেদ করে।
> **প্রমাণ:**
> ১. যেহেতু DA || CE এবং AC তাদের ছেদক,
> সুতরাং, ∠CAD = ∠ACE (একান্তর কোণ)।
> ২. আবার, DA || CE এবং BE তাদের ছেদক,
> সুতরাং, ∠BAD = ∠AEC (অনুরূপ কোণ)।
> ৩. কিন্তু দেওয়া আছে, ∠BAD = ∠CAD (যেহেতু AD কোণটিকে সমদ্বিখণ্ডিত করেছে)।
> অতএব, ∠ACE = ∠AEC।
> ΔACE-এ দুটি কোণ সমান হওয়ায় তাদের বিপরীত বাহুদ্বয় সমান: AE = AC।
> ৪. এখন, ΔBCE-এ DA || CE (অঙ্কনানুসারে)।
> থেলেসের উপপাদ্যানুসারে:
> BD / DC = BA / AE
> যেহেতু AE = AC, তাই:
> BD / DC = AB / AC
> 🎯 **প্রমাণিত:** BD : DC = AB : AC।

$tag_math_ch14$, 1);

