# ১৫শ অধ্যায়: ক্ষেত্রফল সম্পর্কিত উপপাদ্য ও সম্পাদ্য

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*পিথাগোরাসের উপপাদ্য ও এর বিপরীত প্রতিজ্ঞা, সামান্তরিক ও ত্রিভুজক্ষেত্রের ক্ষেত্রফল সম্পর্কিত উপপাদ্য এবং সমান ক্ষেত্রফলবিশিষ্ট ক্ষেত্র অঙ্কন।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> পিথাগোরাসের উপপাদ্য ও এর বিপরীত প্রতিজ্ঞা প্রমাণ করতে পারব;
> একই ভূমি ও একই সমান্তরাল রেখাযুগলের মধ্যস্থিত ত্রিভুজ ও সামান্তরিকের ক্ষেত্রফল তুলনা করতে পারব;
> নির্দিষ্ট বহুভুজের সমান ক্ষেত্রফলবিশিষ্ট ত্রিভুজ বা চতুর্ভুজ অঙ্কন করতে পারব।

### 🔹 বিষয়: পিথাগোরাসের উপপাদ্য ও ক্ষেত্রফলের সম্পর্ক
১. উপপাদ্য ৩৯ (পিথাগোরাসের উপপাদ্য): সমকোণী ত্রিভুজের অতিভুজের উপর অঙ্কিত বর্গক্ষেত্রের ক্ষেত্রফল অপর দুই বাহুর উপর অঙ্কিত বর্গক্ষেত্রদ্বয়ের ক্ষেত্রফলের সমষ্টির সমান।
- অতিভুজ² = লম্ব² + ভূমি² (c² = a² + b²)
২. উপপাদ্য ৪০ (পিথাগোরাসের বিপরীত উপপাদ্য): যদি কোনো ত্রিভুজের একটি বাহুর উপর অঙ্কিত বর্গক্ষেত্র অপর দুই বাহুর উপর অঙ্কিত বর্গক্ষেত্রদ্বয়ের ক্ষেত্রফলের সমষ্টির সমান হয়, তবে শেষোক্ত বাহুদ্বয়ের অন্তর্ভুক্ত কোণটি সমকোণ হবে।
৩. একই ভূমি ও একই সমান্তরাল রেখাযুগলের মধ্যে অবস্থিত ত্রিভুজক্ষেত্রের ক্ষেত্রফল সামান্তরিক ক্ষেত্রের ক্ষেত্রফলের অর্ধেক।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১৫ • উপপাদ্য ৩৯: পিথাগোরাসের উপপাদ্যটি প্রমাণ কর: সমকোণী ত্রিভুজের অতিভুজের উপর অঙ্কিত বর্গক্ষেত্রের ক্ষেত্রফল অপর দুই বাহুর উপর অঙ্কিত বর্গক্ষেত্রদ্বয়ের ক্ষেত্রফলের সমষ্টির সমান।**
> 💡 **সমাধান:**
> **বিশেষ নির্বচন:** মনে করি, ΔABC একটি সমকোণী ত্রিভুজ যার ∠C = এক সমকোণ (৯০°)।
> অতিভুজ AB = c, BC = a এবং AC = b।
> প্রমাণ করতে হবে যে, c² = a² + b²।
> 
> **বীজগাণিতিক প্রমাণ (অঙ্কন):**
> প্রদত্ত সমকোণী ত্রিভুজের সমান করে চারটি সর্বসম সমকোণী ত্রিভুজ এমনভাবে সাজাই যেন বাহুগুলোর সমন্বয়ে (a + b) বাহুবিশিষ্ট একটি বৃহৎ বর্গক্ষেত্র গঠিত হয়।
> ভেতরে c বাহুবিশিষ্ট একটি ছোট বর্গক্ষেত্র তৈরি হয়।
> 
> **গণনা:**
> বৃহৎ বর্গের ক্ষেত্রফল = (a + b)² = a² + 2ab + b²
> আবার, বৃহৎ বর্গের ক্ষেত্রফল = ৪টি ত্রিভুজের ক্ষেত্রফল + ভেতরের ছোট বর্গের ক্ষেত্রফল
> = 4 · (1/2 · a · b) + c²
> = 2ab + c²
> 
> উভয় সমীকরণ সমান করে পাই:
> a² + 2ab + b² = 2ab + c²
> উভয়পক্ষ থেকে 2ab বাদ দিয়ে পাই:
> a² + b² = c²
> বা, c² = a² + b²
> 🎯 **প্রমাণিত:** অতিভুজ² = লম্ব² + ভূমি²।

> 🔢 **অনুশীলনী ১৫ • প্রশ্ন ১১: একটি সমদ্বিবাহু সমকোণী ত্রিভুজের অতিভুজের দৈর্ঘ্য 12 cm হলে এর ক্ষেত্রফল কত?**
> 💡 **সমাধান:**
> **সমাধান:**
> মনে করি, সমদ্বিবাহু সমকোণী ত্রিভুজের সমান সমান বাহুদ্বয়ের দৈর্ঘ্য a cm।
> যেহেতু এটি সমকোণী ত্রিভুজ, পিথাগোরাসের উপপাদ্যানুসারে:
> a² + a² = অতিভুজ²
> বা, 2a² = 12² = 144
> বা, a² = 144 / 2 = 72
> 
> আমরা জানি, সমকোণী ত্রিভুজের ক্ষেত্রফল = 1/2 · ভূমি · উচ্চতা
> = 1/2 · a · a
> = 1/2 · a²
> = 1/2 · 72 = 36 বর্গ সেমি।
> 🎯 **উত্তর:** 36 বর্গ সেমি (cm²)

