# ১৬শ অধ্যায়: পরিমিতি

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*ত্রিভুজ ও চতুর্ভুজের ক্ষেত্রফল, সুষম বহুভুজ, বৃত্তের পরিধি, ক্ষেত্রফল ও বৃত্তকলা, আয়তাকার ঘনবস্তু, ঘনক এবং বেলন (সিলিন্ডার)।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> বিভিন্ন প্রকার ত্রিভুজ ও চতুর্ভুজের ক্ষেত্রফল নির্ণয় করতে পারব;
> বৃত্তের পরিধি, ক্ষেত্রফল ও বৃত্তাংশের ক্ষেত্রফল নির্ণয় করতে পারব;
> আয়তাকার ঘনবস্তু ও ঘনকের সমগ্রতলের ক্ষেত্রফল ও কর্ণের দৈর্ঘ্য নির্ণয় করতে পারব;
> সমবৃত্তভূমিক বেলনের সমগ্রতলের ক্ষেত্রফল ও আয়তন নির্ণয় করতে পারব।

### 🔹 বিষয়: দ্বিমাত্রিক ক্ষেত্রের পরিমিতি সূত্রাবলি
১. ত্রিভুজক্ষেত্রের ক্ষেত্রফল:
- সাধারণ: 1/2 · ভূমি · উচ্চতা
- সমবাহু ত্রিভুজ: (√(3) / 4) · a²
- সমদ্বিবাহু ত্রিভুজ: b/4 · √(4a² - b²) (যেখানে a সমান বাহু, b ভূমি)
- তিন বাহু a, b, c দেওয়া থাকলে: √(s(s - a)(s - b)(s - c)), যেখানে অর্ধ-পরিসীমা s = (a + b + c) / 2
২. চতুর্ভুজক্ষেত্রের ক্ষেত্রফল:
- আয়তক্ষেত্র: দৈর্ঘ্য × প্রস্থ
- বর্গক্ষেত্র: বাহু² = a², কর্ণ = a√(2)
- রম্বস: 1/2 · d₁ · d₂ (কর্ণদ্বয়ের গুণফল)
- ট্রাপিজিয়াম: 1/2 · (সমান্তরাল বাহুদ্বয়ের যোগফল) · উচ্চতা
৩. বৃত্ত সম্পর্কিত:
- পরিধি = 2πr, ক্ষেত্রফল = πr²
- বৃত্তকলার ক্ষেত্রফল = (θ / 360°) · πr²

### 🔹 বিষয়: ত্রিমাত্রিক ঘনবস্তুর পরিমিতি সূত্রাবলি
১. আয়তাকার ঘনবস্তু (দৈর্ঘ্য a, প্রস্থ b, উচ্চতা c):
- সমগ্র পৃষ্ঠের ক্ষেত্রফল = 2(ab + bc + ca)
- আয়তন = abc
- কর্ণের দৈর্ঘ্য = √(a² + b² + c²)
২. ঘনক (বাহু a):
- সমগ্রতলের ক্ষেত্রফল = 6a²
- আয়তন = a³
- কর্ণের দৈর্ঘ্য = a√(3)
৩. সমবৃত্তভূমিক বেলন / সিলিন্ডার (ব্যাসার্ধ r, উচ্চতা h):
- বক্রতলের ক্ষেত্রফল = 2πrh
- সমগ্রতলের ক্ষেত্রফল = 2πr(r + h)
- আয়তন = πr²h

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১৬.১ • প্রশ্ন ৫: একটি সমবাহু ত্রিভুজের প্রত্যেক বাহুর দৈর্ঘ্য 1 মিটার বাড়ালে এর ক্ষেত্রফল 3√(3) বর্গমিটার বৃদ্ধি পায়। ত্রিভুজটির বাহুর দৈর্ঘ্য নির্ণয় কর।**
> 💡 **সমাধান:**
> **সমাধান:**
> মনে করি, সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য a মিটার।
> আমরা জানি, সমবাহু ত্রিভুজের ক্ষেত্রফল = (√(3) / 4) · a² বর্গমিটার।
> 
> বাহুর দৈর্ঘ্য 1 মিটার বাড়ালে বাহু হয় (a + 1) মিটার।
> তখন ক্ষেত্রফল = (√(3) / 4) · (a + 1)² বর্গমিটার।
> 
> প্রশ্নমতে:
> (√(3) / 4) · (a + 1)² - (√(3) / 4) · a² = 3√(3)
> উভয়পক্ষকে (√(3) / 4) দ্বারা ভাগ করে পাই:
> (a + 1)² - a² = 3√(3) / (√(3) / 4)
> বা, a² + 2a + 1 - a² = 3 × 4 = 12
> বা, 2a + 1 = 12
> বা, 2a = 12 - 1 = 11
> বা, a = 11 / 2 = 5.5 মিটার।
> 🎯 **উত্তর:** ত্রিভুজটির বাহুর দৈর্ঘ্য 5.5 মিটার।

> 🔢 **অনুশীলনী ১৬.২ • প্রশ্ন ১: একটি আয়তাকার ক্ষেত্রের দৈর্ঘ্য প্রস্থের দ্বিগুণ। এর ক্ষেত্রফল 512 বর্গমিটার হলে পরিসীমা কত?**
> 💡 **সমাধান:**
> **সমাধান:**
> মনে করি, আয়তাকার ক্ষেত্রটির প্রস্থ = x মিটার।
> সুতরাং, দৈর্ঘ্য = 2x মিটার।
> 
> আমরা জানি, আয়তক্ষেত্রের ক্ষেত্রফল = দৈর্ঘ্য × প্রস্থ
> বা, 2x · x = 512
> বা, 2x² = 512
> বা, x² = 512 / 2 = 256
> বা, x = √(256) = 16 মিটার।
> 
> সুতরাং,
> প্রস্থ = 16 মিটার
> দৈর্ঘ্য = 2 × 16 = 32 মিটার।
> 
> অতএব, পরিসীমা = 2(দৈর্ঘ্য + প্রস্থ)
> = 2(32 + 16)
> = 2(48) = 96 মিটার।
> 🎯 **উত্তর:** পরিসীমা 96 মিটার।

> 🔢 **অনুশীলনী ১৬.৪ • প্রশ্ন ১৯: একটি সমবৃত্তভূমিক বেলনের উচ্চতা 10 cm এবং ভূমির ব্যাসার্ধ 7 cm হলে এর সমগ্রতলের ক্ষেত্রফল এবং আয়তন নির্ণয় কর।**
> 💡 **সমাধান:**
> **সমাধান:**
> দেওয়া আছে,
> বেলনের ভূমির ব্যাসার্ধ r = 7 cm
> বেলনের উচ্চতা h = 10 cm
> এবং π ≈ 3.1416 (বা 22/7)
> 
> **১ম অংশ: সমগ্রতলের ক্ষেত্রফল:**
> সমগ্রতলের ক্ষেত্রফল = 2πr(r + h)
> = 2 × 22/7 × 7 × (7 + 10)
> = 2 × 22 × 17
> = 44 × 17 = 748 বর্গ সেমি (cm²)।
> 
> **২য় অংশ: আয়তন:**
> আয়তন = πr²h
> = 22/7 × 7² × 10
> = 22/7 × 49 × 10
> = 22 × 7 × 10 = 1540 ঘন সেমি (cm³)।
> 🎯 **উত্তর:** সমগ্রতলের ক্ষেত্রফল 748 বর্গ সেমি এবং আয়তন 1540 ঘন সেমি।

