    VALUES (v_chapter_id, $tag_math_ch17$
# ১৭শ অধ্যায়: পরিসংখ্যান

**গণিত • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গণসংখ্যা নিবেশন সারণি, কেন্দ্রীয় প্রবণতার পরিমাপ (সংক্ষিপ্ত পদ্ধতিতে গড়, মধ্যক ও প্রচুরক) এবং আয়তলেখ ও অজিভ রেখা অঙ্কন।*

---

### 🎯 এ অধ্যায় শেষে আমরা যা শিখতে পারব (শিখনফল)

> পরিসংখ্যান উপাত্তের শ্রেণিবিন্যাস এবং গণসংখ্যা সারণি তৈরি করতে পারব;
> সংক্ষিপ্ত পদ্ধতিতে গড় নির্ণয় করতে পারব;
> শ্রেণিকৃত উপাত্তের মধ্যক ও প্রচুরক নির্ণয় করতে পারব;
> আয়তলেখ, বহুভুজ ও ক্রমযোজিত গণসংখ্যার অজিভ রেখা অঙ্কন ও বিশ্লেষণ করতে পারব।

### 🔹 বিষয়: কেন্দ্রীয় প্রবণতার পরিমাপ ও সূত্রাবলি
কেন্দ্রীয় প্রবণতার পরিমাপ তিনটি: গাণিতিক গড় (Mean), মধ্যক (Median) ও প্রচুরক (Mode)।
১. সংক্ষিপ্ত পদ্ধতিতে গড়:
x̄ = a + (∑ fᵢ uᵢ / n) × h
যেখানে, a = আনুমানিক গড়, fᵢ = শ্রেণির গণসংখ্যা, uᵢ = (xᵢ - a) / h = ধাপ বিচ্যুতি, n = মোট গণসংখ্যা, h = শ্রেণিব্যাপ্তি।

২. মধ্যক (Median):
মধ্যক = L + (n / 2 - F꜀) × (h / fₘ)
যেখানে, L = মধ্যক শ্রেণির নিম্নসীমা, n = মোট গণসংখ্যা, F꜀ = মধ্যক শ্রেণির পূর্ববর্তী শ্রেণির ক্রমযোজিত গণসংখ্যা, fₘ = মধ্যক শ্রেণির গণসংখ্যা, h = শ্রেণিব্যাপ্তি।

৩. প্রচুরক (Mode):
প্রচুরক = L + (f₁ / (f₁ + f₂)) × h
যেখানে, L = প্রচুরক শ্রেণির নিম্নসীমা, f₁ = fₘ - fₘ₋₁ (প্রচুরক শ্রেণির গণসংখ্যা - পূর্ববর্তী শ্রেণির গণসংখ্যা), f₂ = fₘ - fₘ₊₁ (প্রচুরক শ্রেণির গণসংখ্যা - পরবর্তী শ্রেণির গণসংখ্যা), h = শ্রেণিব্যাপ্তি।

### 📐 পাঠ্যবইয়ের অনুশীলনীভিত্তিক সমস্যাবলি ও সমাধান (সমাধান দেখতে বাটনে ক্লিক করুন)

> 🔢 **অনুশীলনী ১৭ • প্রশ্ন ১২ (প্রচুরক নির্ণয়): নিচের সারণি থেকে প্রচুরক নির্ণয় কর:
| শ্রেণিব্যাপ্তি | ৩১-৪০ | ৪১-৫০ | ৫১-৬০ | ৬১-৭০ | ৭১-৮০ |
| গণসংখ্যা | ৪ | ৮ | ১২ | ৯ | ৭ |**
> 💡 **সমাধান:**
> **সমাধান:**
> **ধাপ ১ (প্রচুরক শ্রেণি সনাক্তকরণ):**
> এখানে সর্বাধিক গণসংখ্যা 12 রয়েছে (51 - 60) শ্রেণিতে।
> সুতরাং প্রচুরক শ্রেণি হলো (51 - 60)।
> 
> **ধাপ ২ (মানসমূহ চিহ্নিতকরণ):**
> - প্রচুরক শ্রেণির নিম্নসীমা L = 51
> - f₁ = 12 - 8 = 4 (প্রচুরক শ্রেণি ও পূর্ববর্তী শ্রেণির গণসংখ্যার পার্থক্য)
> - f₂ = 12 - 9 = 3 (প্রচুরক শ্রেণি ও পরবর্তী শ্রেণির গণসংখ্যার পার্থক্য)
> - শ্রেণিব্যাপ্তি h = 40 - 31 + 1 = 10
> 
> **ধাপ ৩ (সূত্রে প্রয়োগ ও মান):**
> প্রচুরক = L + (f₁ / (f₁ + f₂)) × h
> = 51 + (4 / (4 + 3)) × 10
> = 51 + 4/7 × 10
> = 51 + 40 / 7 ≈ 51 + 5.71 = 56.71
> 🎯 **উত্তর:** নির্ণেয় প্রচুরক প্রায় 56.71।

> 🔢 **অনুশীলনী ১৭ • প্রশ্ন ১৪ (সংক্ষিপ্ত পদ্ধতিতে গড়): নিচের সারণি হতে সংক্ষিপ্ত পদ্ধতিতে গড় নির্ণয় কর:
| শ্রেণিব্যাপ্তি | ২৫-৩৪ | ৩৫-৪৪ | ৪৫-৫৪ | ৫৫-৬৪ | ৬৫-৭৪ |
| গণসংখ্যা | ৫ | ১০ | ১৫ | ৮ | ২ |**
> 💡 **সমাধান:**
> **সমাধান:**
> মোট গণসংখ্যা n = 5 + 10 + 15 + 8 + 2 = 40।
> শ্রেণিব্যাপ্তি h = 10।
> সর্বোচ্চ গণসংখ্যা 15 রয়েছে (45-54) শ্রেণিতে, যার মধ্যমান xᵢ = (45 + 54) / 2 = 49.5।
> আনুমানিক গড় a = 49.5 ধরি।
> 
> গণনা সারণি:
> - ২৫-৩৪: মধ্যমান 29.5, f = 5, u = (29.5 - 49.5)/10 = -2, fu = 5 × (-2) = -10
> - ৩৫-৪৪: মধ্যমান 39.5, f = 10, u = -1, fu = 10 × (-1) = -10
> - ৪৫-৫৪: মধ্যমান 49.5 (a), f = 15, u = 0, fu = 15 × 0 = 0
> - ৫৫-৬৪: মধ্যমান 59.5, f = 8, u = 1, fu = 8 × 1 = 8
> - ৬৫-৭৪: মধ্যমান 69.5, f = 2, u = 2, fu = 2 × 2 = 4
> 
> ∑ fᵢ uᵢ = -10 - 10 + 0 + 8 + 4 = -8।
> 
> গড় x̄ = a + (∑ fᵢ uᵢ / n) × h
> = 49.5 + (-8 / 40) × 10
> = 49.5 + (-0.2) × 10
> = 49.5 - 2 = 47.5
> 🎯 **উত্তর:** সংক্ষিপ্ত পদ্ধতিতে গড় = 47.5।

